        unsigned sector = 2, head = 0, cyl = 0;   /* LBA 1 = C0 H0 S2 */
        unsigned short seg = 0x1000;              /* -> physical 0x10000 */
        int remaining = KSECTORS;
        while (remaining > 0) {
            unsigned count = 19 - sector;                     /* rest of this track */
            unsigned tb    = (0x1000U - (seg & 0x0FFF)) >> 5; /* sectors to 64K edge */
            if (count > tb)             count = tb;
            if ((int)count > remaining) count = remaining;
            unsigned char al = (unsigned char)count, ch = (unsigned char)cyl;
            unsigned char cl = (unsigned char)sector, dh = (unsigned char)head;
            __asm__ volatile(
                "movw %[es], %%es\n\t"
                "xorw %%bx, %%bx\n\t"
                "movb $0x02, %%ah\n\t"
                "movb %[al], %%al\n\t"
                "movb %[ch], %%ch\n\t"
                "mo

#define BC_MASK (BC_WAYS - 1)
static unsigned int  bc_block[BC_WAYS];
static unsigned char bc_valid[BC_WAYS];
/** Docstring: Cache lines, heap-owned since the .bss diet: 16 x 4096. A
 * null pointer means the allocation failed and the cache stays disabled;
 * every read then goes straight to the device, slower but correct. */
static unsigned char *bc_data = 0;

static unsigned int bc_index(unsigned int block_num) {
    return block_num & BC_MASK;
}

static void bc_invalidate_locked(unsigned int block_num) {
    unsigned int idx = bc_index(block_num);
    if (bc_valid[idx] && bc_block[idx] == block_num) bc_valid[idx] = 0;
}

static void bc_invalidate(unsigned int block_num) {
    irqflags_t flags;
    spin_lock_irqsave(&bc_lock, &flags);
    bc_invalidate_locked(block_num);
    spin_unlock_irqrestore(&bc_lock, flags);
}

void block_init(void) {
    unsigned int ide_total;
    unsigned long vblk_total;
    ide_init();
    ide_total = ide_total_sectors();
    block_total_sectors = ide_total;
    block_lba_base = 0;
    block_use_virtio = 0;
    if (vblk_init()) {
        vblk_register_device();
        vblk_total = vblk_sectors();
        if (ide_total == 0 || vblk_total == (unsigned long)ide_total) {
            block_use_virtio = 1;
            if (vblk_total <= 0xFFFFFFFFu)
                block_total_sectors = (unsigned int)vblk_total;
        }
    }
    if (!block_use_virtio && ubk_init()) {
        block_use_usb = 1;
        if (ubk_sectors() <= 0xFFFFFFFFu)
            block_total_sectors = (unsigned int)ubk_sectors();
    }
    if (nvme_init())
        kprintf("nvme: present VS 0x%x sectors=%lu\n", nvme_version(),
                nvme_sectors());
    else
        kprintf("nvme: %s\n", nvme_note());
    kprintf("block: backend=%s\n", block_use_virtio ? "virtio" :
            block_use_usb ? "usb" : "ide");
    bc_data = (unsigned char *)kmalloc(BC_WAYS * BLOCK_SIZE);
    if (!bc_data) kprintf("block: no cache (out of memory)\n");
}

void block_set_base(unsigned int lba_base) {
    if (lba_base != block_lba_base) {
        unsigned int i;
        for (i = 0; i < BC_WAYS; i++) bc_valid[i] = 0;
        block_lba_base = lba_base;
    }
}

/* Strategy consumer: sector I/O goes through the registered block device's

static int block_dev_read(unsigned lba, unsigned count, void *buf) {
    device_t *d;
    if (block_use_virtio) {
        d = device_find("vblk0");
        if (d && d->block && d->block->read_sectors)
            return d->block->read_sectors(d, lba, count, buf);
    }
    if (block_use_usb) {
        d = device_find("usb");
        if (d && d->block && d->block->read_sectors)
            return d->block->read_sectors(d, lba, count, buf);
    }
    d = device_find("ide0");
    if (d && d->block && d->block->read_sectors)
        return d->block->read_sectors(d, lba, count, buf);
    return ide_read_sectors(lba, count, buf);
}

static int block_dev_write(unsigned lba, unsigned count, const void *buf) {
    device_t *d;
    if (block_use_virtio) {
        d = device_find("vblk0");
        if (d && d->block && d->block->write_sectors)
            return d->block->write_sectors(d, lba, count, buf);
    }
    if (block_use_usb) {
        d = device_find("usb");
        if (d && d->block && d->block->write_sectors)
            return d->block->write_sectors(d, lba, count, buf);
    }
    d = device_find("ide0");
    if (d && d->block && d->block->write_sectors)
        return d->block->write_sectors(d, lba, count, buf);
    return ide_write_sectors(lba, count, buf);
}

int block_read(unsigned int block_num, void *buf) {
    unsigned int idx = bc_index(block_num);
    unsigned char *tmp = 0;
    unsigned int lba;
    unsigned int i;
    unsigned char *dst = (unsigned char *)buf;
    irqflags_t flags;
    if (!buf) return -1;
    spin_lock_irqsave(&bc_lock, &flags);
    if (bc_data && bc_valid[idx] && bc_block[idx] == block_num) {
        unsigned char *src = BC_LINE(idx);
        for (i = 0; i < BLOCK_SIZE; i++) dst[i] = src[i];
        spin_unlock_irqrestore(&bc_lock, flags);
        return 0;
    }
    spin_unlock_irqrestore(&bc_lock, flags);
    tmp = (unsigned char *)kmalloc(BLOCK_SIZE);
    if (!tmp) return -1;
    lba = block_lba_base + block_num * SECTORS_PER_BLOCK;
    if (block_dev_read(lba, SECTORS_PER_BLOCK, tmp) < 0) {
        kfree(tmp);
        return -1;
    }
    spin_lock_irqsave(&bc_lock, &flags);
    if (bc_data && bc_valid[idx] && bc_block[idx] == block_num) {
        unsigned char *src = BC_LINE(idx);
        for (i = 0; i < BLOCK_SIZE; i++) dst[i] = src[i];
    } else if (bc_data) {
        unsigned char *line = BC_LINE(idx);
        for (i = 0; i < BLOCK_SIZE; i++) line[i] = tmp[i];
        bc_block[idx] = block_num;
        bc_valid[idx] = 1;
        for (i = 0; i < BLOCK_SIZE; i++) dst[i] = tmp[i];
    } else {
        for (i = 0; i < BLOCK_SIZE; i++) dst[i] = tmp[i];
    }
    spin_unlock_irqrestore(&bc_lock, flags);
    kfree(tmp);
    return 0;
}

int block_write(unsigned int block_num, const void *buf) {
    unsigned int lba = block_lba_base + block_num * SECTORS_PER_BLOCK;
    int r;
    bc_invalidate(block_num);
    r = block_dev_write(lba, SECTORS_PER_BLOCK, buf);
    bc_invalidate(block_num);
    return r;
}

int block_read_multi(unsigned int block_num, unsigned int count, void *buf) {
    unsigned int lba = block_lba_base + block_num * SECTORS_PER_BLOCK;
    return block_dev_read(lba, count * SECTORS_PER_BLOCK, buf);
}

int block_write_multi(unsigned int block_num, unsigned int count, const void *buf) {
    unsigned int i;
    unsigned int lba = block_lba_base + block_num * SECTORS_PER_BLOCK;
    int r;
    irqflags_t flags;
    spin_lock_irqsave(&bc_lock, &flags);
    for (i = 0; i < count; i++) bc_invalidate_locked(block_num + i);
    spin_unlock_irqrestore(&bc_lock, flags);
    r = block_dev_write(lba, count * SECTORS_PER_BLOCK, buf);
    spin_lock_irqsave(&bc_lock, &flags);
    for (i = 0; i < count; i++) bc_invalidate_locked(block_num + i);
    spin_unlock_irqrestore(&bc_lock, flags);
    return r;
}

unsigned int block_total(void) {
    if (block_total_sectors == 0) return 0;
    return block_total_sectors / SECTORS_PER_BLOCK;
}

/** Docstring: Absolute sector read on the active backend, with no cache
 * and no base offset: partition tables and foreign filesystems address the
 * whole disk, not the MiniFS window. */

int block_read_sectors(unsigned lba, unsigned count, void *buf) {
    unsigned long end;
    if (!buf || count == 0) return -1;
    end = (unsigned long)lba + count;
    if (end > block_total_sectors) return -1;
    if (block_dev_read(lba, count, buf) < 0) return -1;
    return 0;
}

/** Docstring: Size of the active backend in sectors, so scanners fence to
 * the USB stick when it is the backend and not to the IDE disk. */

unsigned long block_disk_sectors(void) {
    return (unsigned long)block_total_sectors;
}

static unsigned dev_len(const char *s) {
    unsigned n = 0;
    while (s[n]) n++;
    return n;
}

static void dev_copy(char *dst, const char *src, unsigned cap) {
    unsigned i = 0;
    if (!cap) return;
    while (i + 1 < cap && src[i]) { dst[i] = src[i]; i++; }
    dst[i] = 0;
}

static int dev_eq(const char *a, const char *b) {
    while (*a && *a == *b) { a++; b++; }
    return *a == *b;
}

void device_reset(void) {
    int i;
    for (i = 0; i < DEV_MAX; i++) {
        dev_table[i].name[0] = 0;
        dev_table[i].type = 0;
        dev_table[i].block = 0;
        dev_table[i].audio = 0;
        dev_table[i].priv = 0;
    }
    dev_used = 0;
}

int device_register(device_t *dev) {
    int i;
    if (!dev || !dev->name[0]) return -1;
    if (dev_len(dev->name) >= DEV_NAME_LEN) return -1;
    for (i = 0; i < DEV_MAX; i++) {
        if (dev_table[i].name[0] && dev_eq(dev_table[i].name, dev->name))
            return -1;
    }
    for (i = 0; i < DEV_MAX; i++) {
        if (!dev_table[i].name[0]) {
            dev_copy(dev_table[i].name, dev->name, DEV_NAME_LEN);
            dev_table[i].type = dev->type;
            dev_table[i].block = dev->block;
            dev_table[i].audio = dev->audio;
            dev_table[i].priv = dev->priv;
            dev_used++;
            return 0;
        }
    }
    return -1;
}

device_t *device_find(const char *name) {
    int i;
    if (!name) return 0;
    for (i = 0; i < DEV_MAX; i++) {
        if (dev_table[i].name[0] && dev_eq(dev_table[i].name, name))
            return &dev_table[i];
    }
    return 0;
}

device_t *device_find_by_type(int type) {
    int i;
    for (i = 0; i < DEV_MAX; i++) {
        if (dev_table[i].name[0] && dev_table[i].type == type)
            return &dev_table[i];
    }
    return 0;
}

int device_count(void) {
    return dev_used;
}

static void ide_delay(void) {
    volatile unsigned i;
    /* A short CPU spin, NOT a port read.  The old loop read the IDE control
     * register 1000 times as a crude timer, which under KVM turns every one of
     * those reads into a VM-exit.  ide_select_drive calls this twice per
     * sector, so reading a 4 MB WAD ran into millions of exits and took
     * minutes.  A pause loop keeps the small settle delay without any I/O. */
    for (i = 0; i < 200; i++) __asm__ volatile("pause");
}

static unsigned char ide_read_status(void) {
    return inb(IDE_PRIMARY_BASE + IDE_REG_STATUS);
}

static int ide_wait_not_busy(unsigned int timeout) {
    unsigned int i;
    for (i = 0; i < timeout; i++) {
        if (!(ide_read_status() & IDE_STATUS_BSY)) return 0;
        /* One port read per pause batch: under KVM each inb is a VM-exit,
         * and QEMU answers status changes in microseconds, so polling
         * every spin burns thousands of exits per wait for no time gain. */
        for (volatile unsigned k = 0; k < 64; k++)
            __asm__ volatile("pause");
    }
    return -1;
}

static int ide_wait_drq(unsigned int timeout) {
    unsigned int i;
    for (i = 0; i < timeout; i++) {
        unsigned char status = ide_read_status();
        if (status & IDE_STATUS_ERR) return -1;
        if (status & IDE_STATUS_DF)  return -1;
        if (status & IDE_STATUS_DRQ) return 0;
        for (volatile unsigned k = 0; k < 64; k++)
            __asm__ volatile("pause");
    }
    return -1;
}

static void ide_select_drive(unsigned char drive) {
    outb(IDE_PRIMARY_BASE + IDE_REG_DRIVE,
         IDE_DRIVE_LBA | (drive ? IDE_DRIVE_SLAVE : IDE_DRIVE_MASTER));
    ide_delay();
}

static void ide_soft_reset(void) {
    outb(IDE_PRIMARY_CTRL, 0x04);
    ide_delay();
    outb(IDE_PRIMARY_CTRL, 0x00);
    ide_delay();
}

static int ide_identify(void) {
    unsigned short buf[256];
    unsigned int i;

    ide_select_drive(0);
    outb(IDE_PRIMARY_BASE + IDE_REG_SECCOUNT, 0);
    outb(IDE_PRIMARY_BASE + IDE_REG_LBA_LO, 0);
    outb(IDE_PRIMARY_BASE + IDE_REG_LBA_MID, 0);
    outb(IDE_PRIMARY_BASE + IDE_REG_LBA_HI, 0);
    outb(IDE_PRIMARY_BASE + IDE_REG_STATUS, IDE_CMD_IDENTIFY);

    if (ide_wait_drq(IDE_TIMEOUT) < 0) return -1;

    for (i = 0; i < 256; i++)
        buf[i] = inw(IDE_PRIMARY_BASE + IDE_REG_DATA);

    if (buf[0] == 0 || buf[0] == 0xFFFF) return -1;

    ide_disk_sectors = ((unsigned int)buf[61] << 16) | buf[60];
    if (ide_disk_sectors == 0 && (buf[83] & 0x0400))
        ide_disk_sectors = ((unsigned int)buf[103] << 16) | buf[102];

    return 0;
}

void ide_init(void) {
    ide_disk_present = 0;
    ide_disk_sectors = 0;

    ide_soft_reset();
    ide_wait_not_busy(IDE_TIMEOUT);
    ide_select_drive(0);
    ide_delay();

    if (ide_identify() == 0) {
        ide_disk_present = 1;
        kprintf("IDE: disk detected, %u sectors (%u MB)\n",
                ide_disk_sectors, ide_disk_sectors / 2048);
    } else {
        kprintf("IDE: no disk on primary master\n");
    }
    ide_register_device();
}

