    if (count == 0 || count > NVME_MAX_SECTORS) return -1;
    if (lba >= xnv_nsze || count > xnv_nsze - lba) return -1;
    bytes = (unsigned long)count * NVME_SECTOR;
    p1 = (unsigned long)xnv_stage;
