    if (!hour || !min || !sec) return 0;
    for (spins = 0; spins < RTC_UPDATE_WAIT; spins++)
        if (!(rtc_cmos_read(RTC_REG_STATUS_A) & RTC_UPDATE_IN_PROGRESS)) break;
    hr = rtc_cmos_read(RTC_REG_HOUR);
    mn = rtc_cmos_read(RTC_REG_MIN);
    sc = rtc_cmos_read(RTC_REG_SEC);
    if (!(rtc_cmos_read(RTC_REG_STATUS_B) & RTC_BCD_FLAG)) {
        hr = rtc_from_bcd((unsigned char)hr);
        mn = rtc_from_bcd((unsigned char)mn);
        sc = rtc_from_bcd((unsigned char)sc);
    }
    if (hr < RTC_HOUR_MIN || hr > RTC_HOUR_MAX ||
        mn < RTC_MIN_MIN || mn > RTC_MIN_MAX ||
        sc < RTC_SEC_MIN || sc > RTC_SEC_MAX)
        return 0;
    *hour = hr;
    *min = mn;
    *sec = sc;
    return 1;
}

static int rtc_month_len(long full_year, long mon) {
    static const unsigned char lens[12] =
        { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
    unsigned char n = lens[mon - 1];
    if (mon == 2 && full_year % 4 == 0 &&
        (full_year % 100 != 0 || full_year % 400 == 0))
        n = 29;
    return (int)n;
}

int rtc_read_date(int *year, int *mon, int *day) {
    int spins;
    int yy, mo, dy;
    long full;
    if (!year || !mon || !day) return 0;
    for (spins = 0; spins < RTC_UPDATE_WAIT; spins++)
        if (!(rtc_cmos_read(RTC_REG_STATUS_A) & RTC_UPDATE_IN_PROGRESS)) break;
    dy = rtc_cmos_read(RTC_REG_DAY);
    mo = rtc_cmos_read(RTC_REG_MON);
    yy = rtc_cmos_read(RTC_REG_YEAR);
    if (!(rtc_cmos_read(RTC_REG_STATUS_B) & RTC_BCD_FLAG)) {
        dy = rtc_from_bcd((unsigned char)dy);
        mo = rtc_from_bcd((unsigned char)mo);
        yy = rtc_from_bcd((unsigned char)yy);
    }
    if (yy < 0 || yy > 99 || mo < 1 || mo > 12) return 0;
    full = 2000L + (long)yy;
    if (dy < 1 || dy > rtc_month_len(full, (long)mo)) return 0;
    *year = (int)full;
    *mon = mo;
    *day = dy;
    return 1;
}

int rtc_wall_seconds(unsigned long *out) {
    int h, m, s, y, mo, dy;
    long days;
    if (!out) return 0;
    if (!rtc_read_tod(&h, &m, &s)) return 0;
    if (!rtc_read_date(&y, &mo, &dy)) return 0;
    days = rtc_days_from_civil((long)y, (long)mo, (long)dy);
    if (days < 0) return 0;
    *out = (unsigned long)days * 86400UL +
           (unsigned long)h * 3600UL +
           (unsigned long)m * 60UL + (unsigned long)s;
    return 1;
}

#define SB16_SQ_CYCLE 512

static int sb16_ready;
static int sb16_mode = SB16_MODE_TONE;
static unsigned sb16_freq;
static unsigned sb16_phase;
static int sb16_inflight;
static unsigned long sb16_last_arm_ms;
static sb16_counters_t sb16_stat;

/* DMA ring state (consumer side: ISR/poll drains these into hardware). */
static unsigned pcm_head;
static unsigned pcm_tail;
static unsigned pcm_free;

/* Multicanal mixer streams.  Each stream has its own ring buffer and volume.
 * sb16_mix_all sums all active streams into the mix buffer before copying
 * into DMA slots. */
static sb16_stream_t streams[SB16_STREAMS];

/* Mixer stream id backing the legacy sb16_pcm_open/submit API (WQ_NONE
 * when closed).  The legacy path forwards into the mixer so submitted
 * PCM actually reaches the DMA ring through sb16_mix_all; a dedicated
 * kernel-side ring here would be a second, never-drained copy. */
static int legacy_stream = WQ_NONE;

/* Reset the legacy kernel-side audio ring to empty. */

static void sb16_kring_reset(void) {
    if (legacy_stream >= 0 && legacy_stream < (int)SB16_STREAMS &&
        streams[(unsigned)legacy_stream].active) {
        streams[(unsigned)legacy_stream].head =
            streams[(unsigned)legacy_stream].tail =
            streams[(unsigned)legacy_stream].count = 0;
    }
}

/* Mix output buffer: one SB16_PCM_BUF chunk of mixed 8-bit unsigned audio. */
static unsigned char mix_buf[SB16_PCM_BUF];

int sb16_stream_open(void) {
    int i;
    for (i = 0; i < (int)SB16_STREAMS; i++) {
        if (!streams[i].active) {
            unsigned char *buf = (unsigned char *)kmalloc(SB16_STREAM_BUF);
            if (!buf) return -1;
            streams[i].active = 1;
            streams[i].ring = buf;
            streams[i].head = streams[i].tail = streams[i].count = 0;
            streams[i].volume = 255;
            return i;
        }
    }
    return -1;
}

void sb16_stream_close(int id) {
    if (id < 0 || id >= (int)SB16_STREAMS) return;
    if (!streams[id].active) return;
    kfree(streams[id].ring);
    streams[id].ring = 0;
    streams[id].active = 0;
}

int sb16_stream_submit(int id, const unsigned char *pcm, unsigned len) {
    unsigned i, free;
    if (id < 0 || id >= (int)SB16_STREAMS) return -1;
    if (!streams[id].active) return -1;
    if (len == 0 || len > SB16_STREAM_BUF) return -1;
    free = SB16_STREAM_BUF - streams[id].count;
    if (len > free) { sb16_stat.drops++; return -1; }
    for (i = 0; i < len; i++)
        streams[id].ring[(streams[id].head + i) % SB16_STREAM_BUF] = pcm[i];
    streams[id].head = (streams[id].head + len) % SB16_STREAM_BUF;
    streams[id].count += len;
    sb16_stat.submits++;
    return 0;
}

void sb16_stream_volume(int id, unsigned char vol) {
    if (id < 0 || id >= (int)SB16_STREAMS) return;
    if (!streams[id].active) return;
    streams[id].volume = vol;
}

static void sb16_mix_all(void) {
    int i;
    unsigned k;
    unsigned len;

    /* Start with silence (0x80 = midpoint for 8-bit unsigned). */
    for (k = 0; k < SB16_PCM_BUF; k++)
        mix_buf[k] = 0x80;

    /* Sum all active streams.  Each stream contributes up to SB16_PCM_BUF
     * bytes from its ring buffer.  Samples are treated as signed for mixing
     * (convert: unsigned 0x80 = signed 0), weighted by volume (0..255), and
     * summed.  The result is clamped to the signed 8-bit range and converted
     * back to unsigned. */
    for (i = 0; i < (int)SB16_STREAMS; i++) {
        sb16_stream_t *s = &streams[i];
        unsigned idx;
        if (!s->active || s->count == 0) continue;
        len = s->count < SB16_PCM_BUF ? s->count : SB16_PCM_BUF;
        /* Running index with a wrap check instead of a per-sample modulo:
         * identical sample sequence, no division in the hot loop. */
        idx = s->tail;
        for (k = 0; k < len; k++) {
            int sample = (int)mix_buf[k] - 128;
            int src = (int)s->ring[idx] - 128;
            sample += (src * (int)s->volume) >> 8;
            if (sample > 127) sample = 127;
            if (sample < -128) sample = -128;
            mix_buf[k] = (unsigned char)(sample + 128);
            idx++;
            if (idx >= SB16_STREAM_BUF) idx = 0;
        }
        s->tail = idx;
        s->count -= len;
    }
    sb16_stat.mixes++;
}

/* ------------------------------------------------------------------ */
/* Pump: drain mixer output into DMA slots and arm the hardware.       */

void sb16_pump(void) {
    int i;
    int busy = 0;
    if (!sb16_ready || sb16_mode != SB16_MODE_PCM) return;
    if (pcm2_active()) return;
    /* No free DMA slot: keep the stream data and retry on the next tick.
     * Mixing here would consume stream bytes that no slot can take, which
     * silently drops audio under load (audible as gaps). */
    if (pcm_free == 0) return;

    /* Idle ticks must not pay a full mix: with no stream holding data the
     * output would be silence, which the arm path already plays from the
     * permanent silence slot on underrun. */
    for (i = 0; i < (int)SB16_STREAMS; i++) {
        if (streams[i].active && streams[i].count > 0) { busy = 1; break; }
    }
    if (!busy) return;

    /* Mix all active streams into mix_buf. */
    sb16_mix_all();

    /* Transfer mixed output into a DMA slot. */
    {
        unsigned char *dst = sb16_slot(pcm_head);
        unsigned i;
        for (i = 0; i < SB16_PCM_BUF; i++)
            dst[i] = mix_buf[i];
        pcm_head = (pcm_head + 1) % SB16_RING_CAP;
        pcm_free--;
        sb16_stat.pump_fills++;
    }

    /* Detect stalls: no data from any stream but DMA ring also empty means
     * all producers stopped and the speaker will go silent. */
    if (pcm_free == SB16_RING_CAP && sb16_inflight)
        sb16_stat.stalls++;
}

/* DSP write-ready: bit 7 of the status port clear means the DSP accepts
 * a command or data byte.  Bounded so a dead DSP can never hang the

static int sb16_wait_write(void) {
    return port_wait_mask(SB16_DSP_STATUS, SB16_DSP_READY_MASK, 0, 100);
}

static void sb16_cmd(unsigned char c) {
    sb16_wait_write();
    outb(SB16_DSP_WRITE_DATA, c);
}

static int sb16_read_data(unsigned char *out) {
    /* Data-ready is bit 7 of the read-status port (0x22E); the byte itself
     * comes from the read-data port (0x22A).  Polling the data port for
     * readiness consumes the pending byte and eats the reply. */
    if (!port_wait_mask(SB16_DSP_RDSTATUS, SB16_DSP_READY_MASK, 1, 100))
        return 0;
    *out = inb(SB16_DSP_READ_DATA);
    return 1;
}

static int sb16_reset_dsp(void) {
    unsigned long end = ktime_ms() + 200;
    int ff = 0;
    unsigned i;
    outb(SB16_DSP_RESET, 1);
    for (i = 0; i < 10000u; i++) __asm__ volatile("pause");
    outb(SB16_DSP_RESET, 0);
    for (i = 0; i < 10000u; i++) __asm__ volatile("pause");
    /* Absent device floats at 0xFF with the ready bit set: without the
     * paired DATA check below, the old loop burned its whole 200k-spin
     * budget (~1 s of KVM exits) on every boot without audio. */
    for (;;) {
        unsigned char st = inb(SB16_DSP_RDSTATUS);
        if (st == 0xFF) {
            if (++ff >= 16) return 0;
        } else {
            ff = 0;
            if (st & SB16_DSP_READY_MASK) {
                if (inb(SB16_DSP_READ_DATA) == 0xAA) return 1;
            }
        }
        if ((long)(ktime_ms() - end) >= 0) return 0;
        for (i = 0; i < 1024; i++) __asm__ volatile("pause");
    }
}

static void sb16_dma_play(unsigned addr, unsigned len) {
    unsigned n = len - 1;
    outb(DMA_MASK, DMA_CH1_MASK);
    outb(DMA_MODE_PORT, DMA_CH1_SINGLE_READ);
    outb(DMA_FF_CLR, 0);
    outb(DMA_CH1_ADDR, addr & 0xFF);
    outb(DMA_CH1_ADDR, (addr >> 8) & 0xFF);
    outb(DMA_CH1_CNT, n & 0xFF);
    outb(DMA_CH1_CNT, (n >> 8) & 0xFF);
    outb(DMA_CH1_PAGE, (addr >> 16) & 0xFF);
    outb(DMA_MASK, DMA_CH1_UNMASK);
    sb16_cmd(SB16_CMD_PLAY8);
    sb16_cmd((unsigned char)((n >> 8) & 0xFF));
    sb16_cmd((unsigned char)(n & 0xFF));
}

static void sb16_refill(int slot_index) {
    unsigned char *buf = sb16_slot((unsigned)slot_index);
    unsigned i;
    if (sb16_freq == 0) {
        for (i = 0; i < SB16_BUF; i++) buf[i] = 0x80;
        return;
    }
    unsigned step = (SB16_SQ_CYCLE * sb16_freq) / SB16_PCM_RATE;
    if (step == 0) step = 1;
    for (i = 0; i < SB16_BUF; i++) {
        buf[i] = (sb16_phase < SB16_SQ_CYCLE / 2) ? 0xC0 : 0x40;
        sb16_phase += step;
        if (sb16_phase >= SB16_SQ_CYCLE) sb16_phase -= SB16_SQ_CYCLE;
    }
}

static void sb16_arm(int from_irq) {
    unsigned long now = ktime_ms();
    if (!sb16_ready || !sb16_inflight) return;
    if (pcm2_active()) return;
    if ((long)(now - sb16_last_arm_ms) < (long)SB16_ARM_PERIOD_MS) return;
    if (sb16_mode == SB16_MODE_PCM) {
        if (pcm_free == SB16_RING_CAP) {
            sb16_dma_play(SB16_DMA_BUF0 + SB16_SILENCE_SLOT * SB16_BUF, SB16_BUF);
        } else {
            sb16_dma_play(SB16_DMA_BUF0 + pcm_tail * SB16_BUF, SB16_BUF);
            pcm_tail = (pcm_tail + 1) % SB16_RING_CAP;
            pcm_free++;
        }
    } else {
        static int tone_next;
        int slot = tone_next;
        tone_next = 1 - tone_next;
        sb16_refill(slot);
        sb16_dma_play(SB16_DMA_BUF0 + (unsigned)slot * SB16_BUF, SB16_BUF);
    }
    sb16_last_arm_ms = now;
    if (from_irq) sb16_stat.irq_arms++;
    else sb16_stat.poll_arms++;
}

void sb16_tone(unsigned freq) {
    if (!sb16_ready) return;
    if (pcm2_active()) return;
    sb16_mode = SB16_MODE_TONE;
    sb16_freq = freq;
    pcm_head = pcm_tail = 0;
    pcm_free = SB16_RING_CAP;
    sb16_kring_reset();
    if (!sb16_inflight) {
        sb16_last_arm_ms = ktime_ms();
        sb16_refill(0);
        sb16_dma_play(SB16_DMA_BUF0, SB16_BUF);
        sb16_inflight = 1;
    }
}

void sb16_pcm_open(void) {
    if (!sb16_ready) return;
    if (pcm2_active()) return;
    sb16_mode = SB16_MODE_PCM;
    sb16_freq = 0;
    pcm_head = pcm_tail = 0;
    pcm_free = SB16_RING_CAP;
    sb16_kring_reset();
    if (legacy_stream == WQ_NONE) {
        int id = sb16_stream_open();
        if (id >= 0) {
            legacy_stream = id;
            sb16_stream_volume(id, 255);
        }
    }
    unsigned i;
    for (i = 0; i < SB16_BUF; i++) sb16_slot(SB16_SILENCE_SLOT)[i] = 0x80;
    if (!sb16_inflight) {
        sb16_last_arm_ms = ktime_ms();
        sb16_dma_play(SB16_DMA_BUF0 + SB16_SILENCE_SLOT * SB16_BUF, SB16_BUF);
        sb16_inflight = 1;
    }
}

void sb16_pcm_close(void) {
    if (!sb16_ready) return;
    if (legacy_stream != WQ_NONE) {
        sb16_stream_close(legacy_stream);
        legacy_stream = WQ_NONE;
    }
    sb16_tone(0);
}

int sb16_pcm_submit(const unsigned char *pcm, unsigned len) {
    if (!sb16_ready || sb16_mode != SB16_MODE_PCM) return -1;
    if (pcm2_active()) return -1;
    if (len == 0 || len > SB16_BUF) return -1;
    if (legacy_stream == WQ_NONE) return -1;

    /* Forward into the mixer stream; sb16_pump (the only consumer feeding
     * the DMA ring) drains it from there.  submit/drop accounting lives in
     * sb16_stream_submit so the wrapper does not double-count. */
    int rc = sb16_stream_submit(legacy_stream, pcm, len);
    if (rc != 0) return -1;

    /* Eagerly pump: if DMA slots are free and data is available,
     * transfer immediately so latency stays low on the fast path. */
    sb16_pump();
    return 0;
}

void sb16_irq(void) {
    if (!sb16_ready || !sb16_inflight) return;
    if (pcm2_active()) return;
    (void)inb(SB16_IRQ_ACK);
    sb16_pump();
    sb16_arm(1);
}

void sb16_poll(void) {
    /* The position poll is the pcm2 IRQ fallback (null backend): it
     * runs on the same audio tick, so no ISR wiring changes. Legacy
     * pump/arm below self-guard on pcm2 ownership. */
    pcm2_poll();
    sb16_pump();
    sb16_arm(0);
}

int sb16_mode_active(void) { return sb16_mode; }

/* Audible legacy ownership for the pcm2 mutual exclusion: a PCM
 * stream is always audible-by-contract, a tone only when sounding.
 * Silent/idle legacy state (probe-only, tone(0)) never blocks pcm2. */

int sb16_legacy_busy(void) {
    if (legacy_stream != WQ_NONE) return 1;
    if (sb16_inflight && sb16_mode == SB16_MODE_PCM) return 1;
    if (sb16_inflight && sb16_freq != 0) return 1;
    return 0;
}

void sb16_counters(sb16_counters_t *out) {
    if (out) *out = sb16_stat;
}

/** Docstring: Strategy verbs publishing the PCM sink to the registry. */

static int sb16_ops_present(device_t *dev)
{
    (void)dev;
    return sb16_present();
}

/** Docstring: Strategy verb for PCM open. */

static void sb16_ops_pcm_open(device_t *dev)
{
    (void)dev;
    sb16_pcm_open();
}

/** Docstring: Strategy verb for PCM close. */

static void sb16_ops_pcm_close(device_t *dev)
{
    (void)dev;
    sb16_pcm_close();
}

/** Docstring: Strategy verb for PCM submit. */

static int sb16_ops_pcm_submit(device_t *dev, const unsigned char *pcm, unsigned len)
{
    (void)dev;
    return sb16_pcm_submit(pcm, len);
}

static const audio_ops_t sb16_audio_ops = {
    .tone = 0,
    .off = 0,
    .set_volume = 0,
    .get_volume = 0,
    .present = sb16_ops_present,
    .pcm_open = sb16_ops_pcm_open,
    .pcm_close = sb16_ops_pcm_close,
    .pcm_submit = sb16_ops_pcm_submit,
};

static device_t sb16_device = {
    "sb160",
    DEV_TYPE_AUDIO,
    0,
    &sb16_audio_ops,
    0,
};

int sb16_init(void) {
    unsigned char major = 0, minor = 0;
    if (sb16_ready) return 1;
    if (!sb16_reset_dsp()) return 0;
    /* The DSP only reports its version after an explicit 0xE1 request;

     * reading without it eats whatever byte happens to be pending (or
     * times out), so the probe used to fail or misread here. */
    sb16_cmd(SB16_CMD_READ_VER);
    if (!sb16_read_data(&major)) return 0;
    if (!sb16_read_data(&minor)) return 0;
    (void)minor;
    if (major < 4) return 0;
    sb16_cmd(SB16_CMD_SET_FREQ);
    sb16_cmd(SB16_FREQ_HI);
    sb16_cmd(SB16_FREQ_LO);
    sb16_cmd(SB16_CMD_SPK_ON);
    sb16_freq = 0;
    sb16_inflight = 0;
    pcm_head = pcm_tail = 0;
    pcm_free = SB16_RING_CAP;
    sb16_ready = 1;
    sb16_last_arm_ms = ktime_ms();
    device_register(&sb16_device);
    return 1;
}

typedef struct {
    int used;
    int device;
    int ep_out;
    int ep_in;
    int ep_out_addr;
    int ep_in_addr;
    int iface;
    unsigned long sectors;
    unsigned tag;
    unsigned char *cbw;
    unsigned char *csw;
    unsigned char *sense;
} ubk_disk_t;

static ubk_disk_t ubk_disk;
static ubk_counters_t ubk_ctr;

/* ---- Endpoint interval and burst ---- */

void ubk_counters(ubk_counters_t *out) {
    if (out) *out = ubk_ctr;
}

/** Docstring: Ten-byte SCSI CDB at the CBW command block: opcode, LBA
 * big-endian, transfer length big-endian. READ(10) and WRITE(10) are ten-byte
 * commands, and a six-byte block with the same opcode is rejected. */

static void ubk_cdb10(unsigned char *cdb, unsigned char opcode,
                      unsigned long lba, unsigned blocks) {
    kmemset(cdb, 0, UBK_CDB_LEN);
    cdb[0] = opcode;
    cdb[2] = (unsigned char)((lba >> 24) & 0xFFu);
    cdb[3] = (unsigned char)((lba >> 16) & 0xFFu);
    cdb[4] = (unsigned char)((lba >> 8) & 0xFFu);
    cdb[5] = (unsigned char)(lba & 0xFFu);
    cdb[7] = (unsigned char)((blocks >> 8) & 0xFFu);
    cdb[8] = (unsigned char)(blocks & 0xFFu);
}

void ubk_build_cbw(unsigned char *out, unsigned tag, unsigned long lba,
                   unsigned blocks, int read, int data_len) {
    unsigned char *cdb = out + UBK_CBW_LEN - 16u;
    kmemset(out, 0, UBK_CBW_LEN);
    out[0] = (unsigned char)(UBK_CBW_SIG & 0xFFu);
    out[1] = (unsigned char)((UBK_CBW_SIG >> 8) & 0xFFu);
    out[2] = (unsigned char)((UBK_CBW_SIG >> 16) & 0xFFu);
    out[3] = (unsigned char)((UBK_CBW_SIG >> 24) & 0xFFu);
    out[4] = (unsigned char)(tag & 0xFFu);
    out[5] = (unsigned char)((tag >> 8) & 0xFFu);
    out[6] = (unsigned char)((tag >> 16) & 0xFFu);
    out[7] = (unsigned char)((tag >> 24) & 0xFFu);
    out[8] = (unsigned char)(data_len & 0xFFu);
    out[9] = (unsigned char)((data_len >> 8) & 0xFFu);
    out[10] = (unsigned char)((data_len >> 16) & 0xFFu);
    out[11] = (unsigned char)((data_len >> 24) & 0xFFu);
    /* The flag bit is set for a device-to-host data stage and clear for a
     * host-to-device one. A device that disagrees rejects the command, which
     * is the safe direction: it cannot misinterpret a write as a read. */
    out[12] = (unsigned char)(read ? UBK_CBW_FLAG_IN : 0x00u);
    out[13] = 0;
    out[14] = UBK_CDB_LEN;
    if (blocks) {
        ubk_cdb10(cdb, (unsigned char)(read ? UBK_SCSI_READ10
                                             : UBK_SCSI_WRITE10),
                  lba, blocks);
    }
}

int ubk_check_csw(const unsigned char *csw, unsigned tag, unsigned expect_len) {
    unsigned sig;
    unsigned got_tag;
    unsigned residue;
    unsigned status;
    if (!csw) return 0;
    sig = (unsigned)csw[0] | ((unsigned)csw[1] << 8) |
          ((unsigned)csw[2] << 16) | ((unsigned)csw[3] << 24);
    if (sig != UBK_CSW_SIG) return 0;
    got_tag = (unsigned)csw[4] | ((unsigned)csw[5] << 8) |
              ((unsigned)csw[6] << 16) | ((unsigned)csw[7] << 24);
    if (got_tag != tag) return 0;
    residue = (unsigned)csw[8] | ((unsigned)csw[9] << 8) |
              ((unsigned)csw[10] << 16) | ((unsigned)csw[11] << 24);
    status = csw[12];
    if (status != UBK_CSW_STATUS_PASSED) return 0;
    if (status != UBK_CSW_STATUS_FAILED && residue != 0u) return 0;
    (void)expect_len;
    return 1;
}

/** Docstring: Bulk-Only Mass Storage Reset on the control endpoint, then
 * CLEAR_FEATURE(ENDPOINT_HALT) on both bulk endpoints and an xHCI
 * stop/reset/re-point of both transfer rings. Real silicon stalls a
 * command it dislikes instead of answering it, and without this no
 * transfer on either endpoint ever completes again. Results are ignored:
 * recovery is best-effort, the retry decides. */

#define UBK_ENDP_HALT 0x00u
static void ubk_reset_recovery(void) {
    ubk_disk_t *d = &ubk_disk;
    unsigned char setup[8];
    setup[0] = 0x21;
    setup[1] = UBK_MS_RESET;
    setup[2] = 0;
    setup[3] = 0;
    setup[4] = (unsigned char)(d->iface & 0xFF);
    setup[5] = 0;
    setup[6] = 0;
    setup[7] = 0;
    xhc_control(d->device, setup, 0, 0, 1);
    setup[0] = 0x02;
    setup[1] = UBK_CLEAR_FEATURE;
    setup[2] = UBK_ENDP_HALT;
    setup[3] = 0;
    setup[4] = (unsigned char)(d->ep_out_addr & 0xFF);
    setup[5] = 0;
    setup[6] = 0;
    setup[7] = 0;
    xhc_control(d->device, setup, 0, 0, 1);
    setup[4] = (unsigned char)(d->ep_in_addr & 0xFF);
    xhc_control(d->device, setup, 0, 0, 1);
    xhc_reset_endpoint(d->device, d->ep_out);
    xhc_reset_endpoint(d->device, d->ep_in);
}

/** Docstring: Six-byte SCSI block: opcode first, the rest zeroed here by
 * the caller through len. TEST UNIT READY and REQUEST SENSE are six-byte
 * commands; sending them in a ten-byte wrapper confuses strict firmware. */

static int ubk_command_raw(unsigned char *cdb, unsigned cdb_len,
                           unsigned char opcode, void *data,
                           unsigned data_len, int to_device) {
    ubk_disk_t *d = &ubk_disk;
    unsigned char *cdb_tail;
    int got = 0;
    unsigned tag;

    if (!d->used) return 0;
    if (!d->cbw || !d->csw) return 0;
    if (cdb_len != UBK_CDB6_LEN && cdb_len != UBK_CDB_LEN) return 0;
    if (data_len > UBK_MAX_XFER_BLOCKS * UBK_BLOCK_SIZE) return 0;

    tag = ++d->tag;
    cdb_tail = d->cbw + UBK_CBW_LEN - 16u;
    kmemset(d->cbw, 0, UBK_CBW_LEN);
    d->cbw[0] = (unsigned char)(UBK_CBW_SIG & 0xFFu);
    d->cbw[1] = (unsigned char)((UBK_CBW_SIG >> 8) & 0xFFu);
    d->cbw[2] = (unsigned char)((UBK_CBW_SIG >> 16) & 0xFFu);
    d->cbw[3] = (unsigned char)((UBK_CBW_SIG >> 24) & 0xFFu);
    d->cbw[4] = (unsigned char)(tag & 0xFFu);
    d->cbw[5] = (unsigned char)((tag >> 8) & 0xFFu);
    d->cbw[6] = (unsigned char)((tag >> 16) & 0xFFu);
    d->cbw[7] = (unsigned char)((tag >> 24) & 0xFFu);
    d->cbw[8] = (unsigned char)(data_len & 0xFFu);
    d->cbw[9] = (unsigned char)((data_len >> 8) & 0xFFu);
    d->cbw[10] = (unsigned char)((data_len >> 16) & 0xFFu);
    d->cbw[11] = (unsigned char)((data_len >> 24) & 0xFFu);
    d->cbw[12] = (unsigned char)(data_len == 0 ? 0x00u :
                                     to_device ? 0x00u : UBK_CBW_FLAG_IN);
    d->cbw[13] = 0;
    d->cbw[14] = (unsigned char)cdb_len;
    kmemcpy(cdb_tail, cdb, cdb_len);

    ubk_ctr.commands++;
    if (!xhc_transfer(d->device, d->ep_out, d->cbw, UBK_CBW_LEN, &got) ||

static void ubk_sense(void) {
    ubk_disk_t *d = &ubk_disk;
    unsigned char cdb[UBK_CDB6_LEN];
    if (!d->used || !d->sense) return;
    kmemset(cdb, 0, UBK_CDB6_LEN);
    cdb[0] = UBK_SCSI_REQUEST_SENSE;
    cdb[4] = UBK_SENSE_LEN;
    if (ubk_command_raw(cdb, UBK_CDB6_LEN, UBK_SCSI_REQUEST_SENSE, d->sense,
                        UBK_SENSE_LEN, 0))
        kprintf("ubk dbg: sense %02x %02x %02x\n", d->sense[0], d->sense[2],
                d->sense[12]);
}

/** Docstring: One command with a single recovery: on a transport failure
 * the pipe is reset and cleared and the command runs once more, because
 * real silicon stalls commands an emulator accepts. A second failure, or
 * a CSW that disagrees, is reported as-is. */

static int ubk_command(unsigned char *cdb, unsigned cdb_len,
                       unsigned char opcode, void *data, unsigned data_len,
                       int to_device) {
    if (ubk_command_raw(cdb, cdb_len, opcode, data, data_len, to_device))
        return 1;
    ubk_reset_recovery();
    ubk_sense();
    return ubk_command_raw(cdb, cdb_len, opcode, data, data_len, to_device);
}

/** Docstring: Wait for the medium with TEST UNIT READY. Real devices answer
 * CHECK CONDITION until the media is up; without this the first capacity
 * read runs against a device that is not there yet. Bounded, so a dead
 * device costs tries, never the boot. */

static int ubk_unit_ready(void) {
    unsigned i;
    unsigned char cdb[UBK_CDB6_LEN];
    kmemset(cdb, 0, UBK_CDB6_LEN);
    cdb[0] = UBK_SCSI_TEST_UNIT_READY;
    for (i = 0; i < UBK_READY_TRIES; i++) {
        if (ubk_command_raw(cdb, UBK_CDB6_LEN, UBK_SCSI_TEST_UNIT_READY, 0,
                            0, 0))
            return 1;
        ubk_sense();
    }
    return 0;
}

/** Docstring: Read the sector count with READ CAPACITY(10). Returns 1 on a
 * successful command with a plausible count. Both fields arrive big-endian,
 * so a little-endian read reports a capacity the medium does not have. */

static int ubk_read_capacity(unsigned long *sectors) {
    unsigned char cdb[UBK_CDB_LEN];
    unsigned char *cap;
    unsigned last;
    unsigned block_size;
    int ok;
    cap = (unsigned char *)kmalloc(8);
    if (!cap) return 0;
    kmm_make_uncached((unsigned long)cap, 8);
    ubk_cdb10(cdb, UBK_SCSI_READ_CAPACITY, 0, 0);
    ok = ubk_command(cdb, UBK_CDB_LEN, UBK_SCSI_READ_CAPACITY, cap, 8, 0);
    if (ok) {
        last = ((unsigned)cap[0] << 24) | ((unsigned)cap[1] << 16) |
               ((unsigned)cap[2] << 8) | (unsigned)cap[3];
        block_size = ((unsigned)cap[4] << 24) | ((unsigned)cap[5] << 16) |
                     ((unsigned)cap[6] << 8) | (unsigned)cap[7];
        if (block_size != UBK_BLOCK_SIZE || last == 0xFFFFFFFFu) {
            kprintf("ubk dbg: capacity last=%08x bs=%u\n", last, block_size);
            ok = 0;
        } else *sectors = (unsigned long)last + 1u;
    }
    kfree(cap);
    return ok;
}

int ubk_present(void) {
    return ubk_disk.used;
}

unsigned long ubk_sectors(void) {
    return ubk_disk.used ? ubk_disk.sectors : 0u;
}

/** Docstring: Move whole sectors. Every refusal is checked before the command
 * is built, so a bad range never reaches the device, and a failed CSW never
 * leaves a buffer described as valid. */

static int ubk_xfer(unsigned long lba, unsigned count, void *buf, int read) {
    unsigned char cdb[UBK_CDB_LEN];
    unsigned long end;
    if (!ubk_disk.used) return 0;
    if (count == 0 || count > UBK_MAX_XFER_BLOCKS) return 0;
    end = lba + count;
    if (end < lba) return 0;
    if (end > ubk_disk.sectors) return 0;
    ubk_cdb10(cdb, (unsigned char)(read ? UBK_SCSI_READ10 : UBK_SCSI_WRITE10),
              lba, count);
    if (!ubk_command(cdb, UBK_CDB_LEN, cdb[0], buf, count * UBK_BLOCK_SIZE,
                     !read))
        return 0;
    if (read) ubk_ctr.read_blocks += count;
    else ubk_ctr.write_blocks += count;
    return 1;
}

int ubk_read_sectors(unsigned long lba, unsigned count, void *buf) {
    if (!buf) return 0;
    return ubk_xfer(lba, count, buf, 1);
}

int ubk_write_sectors(unsigned long lba, unsigned count, const void *buf) {
    if (!buf) return 0;
    return ubk_xfer(lba, count, (void *)(unsigned long)buf, 0);
}

/** Docstring: Take a bulk OUT and a bulk IN endpoint from a claimed interface
 * and program them. Returns 1 on success. */

static int ubk_claim_eps(int device, const xhc_iface_t *iface) {
    int i;
    int out_addr = 0;
    int in_addr = 0;
    int out_maxp = 0;
    int in_maxp = 0;
    for (i = 0; i < iface->num_eps; i++) {
        if (iface->ep_type[i] != XHC_EP_BULK) continue;
        if (iface->ep_addr[i] & XHC_EP_DIR_IN) {
            if (!in_addr) {
                in_addr = iface->ep_addr[i];
                in_maxp = iface->ep_maxp[i];
            }
        } else {
            if (!out_addr) {
                out_addr = iface->ep_addr[i];
                out_maxp = iface->ep_maxp[i];
            }
        }
    }
    if (!in_addr || !out_addr) return 0;
    if (out_maxp > 1024 || in_maxp > 1024) return 0;
    /* Endpoint indices 1 and 2 are the OUT and IN contexts, matching the
     * order every BOT interface uses, and are free unless HID claimed them. */
    if (!xhc_configure_endpoint(device, 1, out_addr, XHC_EP_BULK,
                                out_maxp, 1, UBK_BULK_INTERVAL, UBK_BULK_BURST))
        return 0;
    if (!xhc_configure_endpoint(device, 2, in_addr, XHC_EP_BULK,
                                in_maxp, 1, UBK_BULK_INTERVAL, UBK_BULK_BURST))
        return 0;
    ubk_disk.ep_out = 1;
    ubk_disk.ep_in = 2;
    ubk_disk.ep_out_addr = out_addr;
    ubk_disk.ep_in_addr = in_addr;
    ubk_disk.iface = iface->iface;
    return 1;
}

