    raw = kmalloc(VNET_QAREA + 0xFFFu);
    if (!raw) return 0;
    page = (unsigned char *)(((unsigned long)raw + 0xFFFu) & ~0xFFFuL);
    for (i = 0; i < VNET_QAREA; i++) page[i] = 0;
    pfn = (unsigned long)page >> 12;
