static unsigned xhc_stride(void) {
    return xhc_csz ? XHC_CTX_SLOT_STRIDE64 : XHC_CTX_SLOT_STRIDE;
}

static xhc_trb_t *xhc_cmd;
static unsigned xhc_cmd_enq;
static unsigned xhc_cmd_gen;
static xhc_trb_t *xhc_evt;
