static int ext_mbr_entry(const unsigned char *mbr, int idx,
                         unsigned long total_sec,
                         unsigned long *base_out) {
    const unsigned char *e = mbr + 0x1BE + idx * 16;
    unsigned long start, count;
    fsimg_t probe;
    ext_geo_t g;
    if (e[4] != EXT4_MBR_LINUX) return -1;
    start = (unsigned long)e[8] | ((unsigned long)e[9] << 8) |
        ((unsigned long)e[10] << 16) | ((unsigned long)e[11] << 24);
    count = (unsigned long)e[12] | ((unsigned long)e[13] << 8) |
        ((unsigned long)e[14] << 16) | ((unsigned long)e[15] << 24);
    if (start == 0 || count == 0) return -1;
    if (start >= total_sec || count > total_sec - start) return -1;
    probe.rf = 0;
    probe.ino = -1;
    probe.is_dev = 1;
    probe.dev_lba = start;
    probe.size = count * 512UL;
    if (probe.size > 0xFFFFFFFFUL) return -1;
    if (ext_parse_sb(&probe, &g) < 0) return -1;
    *base_out = start;
    return 0;
}

static int ext_scan_dev(unsigned long total_sec,
                        unsigned long *base_out) {
    unsigned long lba;
    for (lba = 2048; lba < total_sec; lba += 2048) {
        fsimg_t probe;
        ext_geo_t g;
        probe.rf = 0;
        probe.ino = -1;
        probe.is_dev = 1;
        probe.dev_lba = lba;
        probe.size = (total_sec - lba) * 512UL;
        if (probe.size > 0xFFFFFFFFUL) probe.size = 0xFFFFFFFFUL;
        if (ext_parse_sb(&probe, &g) < 0) continue;
        *base_out = lba;
        return 0;
    }
    return -1;
}

static long ext_dev_cached = -1;

long ext_dev_base(void) {
    unsigned char *mbr = (unsigned char *)kmalloc(512);
    unsigned long total;
    unsigned long base;
    int i;
    int rc = -2;
    if (ext_dev_cached != -1) return ext_dev_cached;
    ext_dev_cached = -2;
    if (!mbr) return -2;
    total = block_disk_sectors();
    if (total < 2048) goto out;
    if (block_read_sectors(0, 1, mbr) < 0) goto out;
    if (mbr[510] == 0x55 && mbr[511] == 0xAA &&
        mbr[0x1BE + 4] != 0xEE) {
        for (i = 0; i < 4; i++) {
            if (ext_mbr_entry(mbr, i, total, &base) == 0) {
                ext_dev_cached = (long)base;
                rc = ext_dev_cached;
                goto out;
            }
        }
    }
    if (ext_scan_dev(total, &base) == 0) {
        ext_dev_cached = (long)base;
        rc = ext_dev_cached;
    }
out:
    kfree(mbr);
    return rc;
}

static unsigned fat_ld16(const unsigned char *p) {
    return (unsigned)p[0] | ((unsigned)p[1] << 8);
}

static unsigned fat_ld32(const unsigned char *p) {
    return (unsigned)p[0] | ((unsigned)p[1] << 8) |
        ((unsigned)p[2] << 16) | ((unsigned)p[3] << 24);
}

/* Open by resolved path: files first (a real file named hd0 keeps
 * working), the hd0 disk device only as a fallback. */

static int fat_img_open(const char *resolved, fsimg_t *img) {
    long base;
    unsigned long total;
    if (fsimg_open_file(resolved, img) == 0) return 0;
    if (kstrcmp(resolved, "hd0") != 0) {
        kprintf("fat dbg: not hd0\n");
        return -1;
    }
    total = block_disk_sectors();
    if (total == 0) {
        kprintf("fat dbg: no disk\n");
        return -1;
    }
    base = fat_dev_base();
    if (base < 0) return -1;
    return fsimg_open_dev((unsigned long)base, total - (unsigned long)base,
