typedef struct {
    unsigned byts_per_sec;
    unsigned sec_per_clus;
    unsigned rsvd_sec;
    unsigned num_fats;
    unsigned fatsz_sec;
    unsigned root_clus;
    unsigned long data_off;
    unsigned nclus;
