        if (f->wbuf) kfree(f->wbuf);
        kfree(f);
        return 0;
    }
    if (f->is_pipe) {
        int drop = 0;
        fs_take(&flags);
        if (f->pipe_write && f->pring) pipe_ring_close_writer(f->pring);
        if (f->pring_ref) {
