    for (i = 0; i < PCACHE_PAGES; i++) {
        if (pc_slots[i].valid && pc_slots[i].ino == ino &&
                pc_slots[i].index == index) {
            pc_slots[i].ref++;
            slot = i;
            break;
        }
    }
    spin_unlock_irqrestore(&pc_lock, flags);
    return slot;
