        if (want_set ? (s & mask) : !(s & mask)) return 1;
        if (s == 0xFF) {
            if (++ff >= 16) return 0;
        } else {
            ff = 0;
        }
        if ((long)(ktime_ms() - end) >= 0) return 0;
        for (volatile unsigned i = 0; i < 1024; i++)
