struct lk_block {
    const char *file;
    int line;
    size_t size;
    lk_block_t *next;
    lk_block_t *prev;
};

/** Docstring: tracked malloc, records caller file and line. */
extern void *lk_malloc(size_t size, const char *file, int line);

