static inline void tls_random(unsigned char *out, unsigned len) {
    int fd = open("/dev/urandom", O_RDONLY);
    unsigned got = 0;
    if (fd >= 0) {
        while (got < len) {
            ssize_t n = read(fd, out + got, len - got);
            if (n <= 0) break;
            got += (unsigned)n;
        }
        close(fd);
    }
    while (got < len) out[got++] = (unsigned char)(rand() & 255);
}

