static inline unsigned long vga_fx_rand(unsigned long *s)
{
    unsigned long x;
    if (s == 0) {
        return 1;
    }
    x = *s;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    *s = x;
    return x ? x : 1;
