{
    int ids[4];
    int n = 0;
    int at = -1;
    int i;
    int k;
    if (present == 0 || nterms <= 0) {
        return focus;
    }
    for (i = 0; i < nterms; i++) {
        if (present[i]) {
            if (n < 4) {
                ids[n++] = i;
            }
        }
    }
    if (gfx_active) {
        if (n < 4) {
            ids[n++] = WM_WINDOW_GFX_ID;
        }
    }
    if (n < 2) {
