    for (i = 0; i < nterms && n < cap; i++) {
        if (present[i] && i != focus) {
            order[n++] = i;
        }
    }
    for (i = 0; i < nterms && n < cap; i++) {
        if (present[i] && i == focus) {
            order[n++] = i;
        }
    }
    return n;
}

