 * candidate rather than a device discovered too late to be used. This is
 * a probe that finds nothing on a machine with no xHCI controller, and
 * the boot is unchanged in that case. The controller needs the page

 * tables (already built above) for its uncached register window and the
 * heap for its rings, and it needs no interrupt, so it runs before the IDT
 * exists without risk. */
if (xhc_init()) {
    unsigned version = 0;
    unsigned slots = 0;
    unsigned ports = 0;
    int found = xhc_enumerate_all();
    int hid;
    xhc_info(&version, &slots, &ports, 0);
    kprintf("usb: xHCI %u.%u, %u slots, %u ports, %d devices\n",
            (version >> 8) & 0xFFu, version & 0xFFu, slots, ports, found);
    hid = usbhid_init();
    if (hid)
        kprintf("usb: hid kbd=%d mouse=%d\n", usbhid_keyboard_present(),
                usbhid_mouse_present());
}

block_init();
pcache_init();
minifs_init();
bootlog_mark("block+minifs");
if (ide_present() || vblk_present() || ubk_present()) {
    if (minifs_mount() < 0) {
        kprintf("minifs: no filesystem found on disk\n");
    }
}

/* Register VFS drivers.  Ramdisk is always available; MiniFS is
 * registered only when the IDE disk was found and mounted. */
vfs_register_builtins();

kprintf("Heap: %d MB  Symbols: %d  (Linux ELF: syscall ABI ready)\n",
        (int)(HEAP_SIZE >> 20), ksym_count);

/* Initialize the scheduler: IDT, TSS, PIC, PIT timer.
 * This enables interrupts and the 100 Hz timer tick. */
sched_init();
kprintf("Scheduler: IDT 256 entries, TSS loaded, PIT 100 Hz, preemptive\n");
bootlog_mark("sched");

static int abi_parse_num(const char **pp, const char *end, unsigned long *out) {
    const char *p = *pp;
    unsigned long v = 0;
    if (p >= end || *p < '0' || *p > '9')
        return 0;
    while (p < end && *p >= '0' && *p <= '9') {
        unsigned digit = (unsigned)(*p - '0');
        if (v > (0xFFFFFFFFFFFFFFFFUL - digit) / 10)
            return 0;
        v = v * 10 + digit;
        p++;
    }
    *pp = p;
    *out = v;
    return 1;
}

/** Docstring: Verify manifest text against the running ABI. */

int abi_verify(const char *text, long version, unsigned long checksum) {
    const char *p, *end;
    unsigned long v = 0, c = 0;
    int i;
    if (!text)
        return ABI_BAD_FORMAT;
    for (i = 0; i < ABI_MANIFEST_MAX && text[i]; i++)
        ;
    if (i >= ABI_MANIFEST_MAX)
        return ABI_BAD_FORMAT;
    p = text;
    end = text + i;
    if (p + 2 > end || p[0] != 'v' || p[1] != '=')
        return ABI_BAD_FORMAT;
    p += 2;
    if (!abi_parse_num(&p, end, &v))
        return ABI_BAD_FORMAT;
    if (p >= end || *p != ' ')
        return ABI_BAD_FORMAT;
    p++;
    if (p + 2 > end || p[0] != 'c' || p[1] != '=')
        return ABI_BAD_FORMAT;
    p += 2;
    if (!abi_parse_num(&p, end, &c))
        return ABI_BAD_FORMAT;
    if (p + 1 != end || *p != '\n')
        return ABI_BAD_FORMAT;
    if ((long)v != version)
        return ABI_VERSION_MISMATCH;
    if (c != checksum)
        return ABI_CHECKSUM_MISMATCH;
    return ABI_OK;
}

#ifndef ABI_HOST_TEST
/** Docstring: Read etc/abi from the ramdisk and verify the running ABI. */

int abi_check_manifest(void) {
    RDFile *f = ramdisk_open(ABI_MANIFEST_NAME);
    char buf[ABI_MANIFEST_MAX];
    int i, rc;
    if (!f)
        return ABI_NO_MANIFEST;
    if (f->size == 0 || f->size >= (unsigned)ABI_MANIFEST_MAX)
        return ABI_BAD_FORMAT;
    for (i = 0; i < ABI_MANIFEST_MAX; i++)
        buf[i] = 0;
    if (ramdisk_read(f, buf, 0, f->size) != (int)f->size)
        return ABI_BAD_FORMAT;
    buf[f->size] = 0;
    rc = abi_verify(buf, (long)MINIOS_ABI_VERSION,
                    (unsigned long)MINIOS_ABI_CHECKSUM);
    return rc;
}
#endif

long batch_exec(const batch_op_t *ops, long *results, int count,
                int *completed, batch_handler_t dispatch) {
    int i;
    if (completed)
        *completed = 0;
    if (count < 0 || count > BATCH_MAX_OPS)
        return BATCH_ERR_COUNT;
    if (count > 0 && (!ops || !results || !completed || !dispatch))
        return BATCH_ERR_PTR;
    for (i = 0; i < count; i++) {
        uint32_t op = ops[i].opcode;
        long r;
        if (op != BATCH_OP_NOP && op != BATCH_OP_YIELD &&
            op != BATCH_OP_TIME && op != BATCH_OP_GETPID)
            return BATCH_ERR_OPCODE;
        r = dispatch(op);
        if (r < 0)
            return r;
        results[i] = r;
        *completed = i + 1;
    }
    return BATCH_OK;
}

#define CLIP_MAX 4096

static char clip_buf[CLIP_MAX];
static unsigned clip_len;
static int clip_valid;

/** Docstring: Replace the clipboard with len bytes from data. Refused
 * (return -1) on null data or past CLIP_MAX; empty clears. */

int clip_set(const char *data, unsigned long len) {
    unsigned long i;
    if (!data) return -1;
    if (len > CLIP_MAX) return -1;
    for (i = 0u; i < len; i++) clip_buf[i] = data[i];
    clip_len = (unsigned)len;
    clip_valid = 1;
    return 0;
}

/** Docstring: Copy the clipboard into out (cap bytes). Returns the
 * length, or -1 when empty/cleared. Fail-closed on an undersize
 * buffer (refuse, never a silently truncated paste). */
int clip_get(char *out, unsigned long cap) {
    unsigned long i;
    if (!out || cap == 0u) return -1;
    if (!clip_valid || clip_len == 0u) return -1;
    if ((unsigned long)clip_len > cap) return -1;
    for (i = 0u; i < clip_len; i++) out[i] = clip_buf[i];
    return (int)clip_len;
}

/** Docstring: Empty the clipboard. Reads then report -1 (empty). */

void clip_clear(void) {
    clip_len = 0u;
    clip_valid = 0;
}

/** Docstring: Current length, or -1 when empty. Lets callers size the
 * read buffer before getting. */

int clip_len_get(void) {
    if (clip_valid && clip_len > 0u) return (int)clip_len;
    return -1;
}

#define XXH_STATIC_LINKING_ONLY
#include "xxhash.h"
#include "stb/stb_api.h"

/* console.c -- Execution-context output: text console, capture, libc names.
 *
 * Bounded Context (DDD): all character-console output lives here. kernel.c
 * keeps only orchestration (kmain) and the syscall trampoline; it owns no
 * console state and no libc table. Consumers call vga_putc/vga_puts,
 * redirect_* and register_libc_symbols through kernel.h. */

static int vga_x, vga_y;
static char vga_color = 0x07;

void vga_clear(void) {
    int i;
    for (i = 0; i < VGA_COLS * VGA_ROWS; i++) {
        VGA_BASE[i * 2]     = ' ';
        VGA_BASE[i * 2 + 1] = vga_color;
    }
    vga_x = vga_y = 0;
    vga_set_cursor(0, 0);
    sb_reset();
}

void vga_set_cursor(int x, int y) {
    unsigned short pos = (unsigned short)(y * VGA_COLS + x);
    unsigned char lo = pos & 0xFF;
    unsigned char hi = (pos >> 8) & 0xFF;
    __asm__ volatile(
        "movw $0x3D4, %%dx\n\t"
        "movb $0x0F, %%al\n\t"
        "outb %%al, %%dx\n"
        "movb %b0, %%al\n\t"
        "outb %%al, %%dx\n"
        "movb $0x0E, %%al\n\t"
        "outb %%al, %%dx\n"
        "movb %b1, %%al\n\t"
        "outb %%al, %%dx"
        :
        : "r"((unsigned long)lo), "r"((unsigned long)hi)
        : "ax", "dx"
    );
}

void vga_scroll(void) {
    int y, x;
    sb_capture_row0();
    for (y = 0; y < VGA_ROWS - 1; y++) {
        for (x = 0; x < VGA_COLS; x++) {
            unsigned src = vga_offset(x, y + 1);
            unsigned dst = vga_offset(x, y);
            VGA_BASE[dst]     = VGA_BASE[src];
            VGA_BASE[dst + 1] = VGA_BASE[src + 1];
        }
    }
    for (x = 0; x < VGA_COLS; x++) {
        unsigned off = vga_offset(x, VGA_ROWS - 1);
        VGA_BASE[off]     = ' ';
        VGA_BASE[off + 1] = vga_color;
    }
    vga_y = VGA_ROWS - 1;
}

void vga_newline(void) {
    vga_x = 0;
    vga_y++;
    if (vga_y >= VGA_ROWS) vga_scroll();
}

void vga_cursor_enable(int on) {
    outb(0x3D4, 0x0A);
    unsigned char v = inb(0x3D5);
    if (on) v &= 0xDF; else v |= 0x20;
    outb(0x3D5, v);
}

static void vga_raw_space(void) {
    unsigned off = vga_offset(vga_x, vga_y);
    VGA_BASE[off]     = ' ';
    VGA_BASE[off + 1] = vga_color;
    vga_x++;
    if (vga_x >= VGA_COLS) vga_newline();
}

#define REDIR_MAX_BYTES   (16UL * 1024 * 1024)

/** Docstring: persistent bump arena for console captures. The block only
 * grows (16 KB seed, doubling to a 16 MB cap) and every begin/commit/
 * take/discard rewinds the length to zero without freeing, so repeated
 * Ctrl+R / Ctrl+L toolchain runs reuse one buffer instead of churning
 * the dlmalloc heap once per build. */
static char         *redir_buf;
static unsigned long  redir_len;
static unsigned long  redir_cap;
static int            redir_active;
static int            redir_overflow;

static int redir_grow(void) {
    unsigned long want = redir_cap ? redir_cap * 2 : REDIR_INITIAL_CAP;
    if (want > REDIR_MAX_BYTES) return 0;
    char *grown = krealloc(redir_buf, want);
    if (!grown) return 0;
    redir_buf = grown;
    redir_cap = want;
    return 1;
}

static int redirect_putc(char c) {
    if (!redir_active) return 0;
    if (redir_len < redir_cap || redir_grow()) redir_buf[redir_len++] = c;
    else redir_overflow = 1;
    return 1;
}

int redirect_suspend(void) {
    int was = redir_active;
    redir_active = 0;
    return was;
}

void redirect_resume(int was) {
    redir_active = was;
}

int redirect_begin(void) {
    redir_len      = 0;
    redir_overflow = 0;
    if (!redir_buf && !redir_grow()) return 0;
    redir_active = 1;
    return 1;
}

int redirect_commit(const char *path, int append_mode) {    KFILE *f;
    unsigned long written;
    int rc;

    redir_active = 0;
    if (redir_overflow) { redir_len = 0; return -1; }

    f = kfopen(path, append_mode ? "a" : "w");
    if (!f) { redir_len = 0; return -1; }
    written = redir_len ? kfwrite(redir_buf, 1, redir_len, f) : 0;
    rc = kfclose(f);
    if (redir_len && written != redir_len) rc = -1;
    redir_len = 0;
    return rc;
}

/** Docstring: Take the captured output as a heap buffer instead of
 * committing it to a file. Deactivates the capture, hands a malloc'd
 * copy (caller frees) with its length, and resets the ring. The shell
 * pipeline runner owns this: stage N's output becomes stage N+1's
 * stdin. Fail-closed: NULL with len 0 on empty capture or OOM. */
char *redirect_take(unsigned long *len_out) {    char *out = 0;
    unsigned long i;
    redir_active = 0;
    if (len_out) *len_out = 0;
    if (redir_overflow || redir_len == 0) { redir_len = 0; return 0; }
    out = kmalloc(redir_len + 1);
    if (!out) { redir_len = 0; return 0; }
    for (i = 0; i < redir_len; i++) out[i] = redir_buf[i];
    out[redir_len] = 0;
    if (len_out) *len_out = redir_len;
    redir_len = 0;
    return out;
}

/** Docstring: Bytes waiting in the capture, 0 when idle or overflowed.
 * Lets a caller size one arena block for the whole capture instead of
 * taking a throwaway heap copy first. */

unsigned long redirect_pending(void) {
    if (redir_overflow || redir_len == 0) return 0;
    return redir_len;
}

/** Docstring: Drain the capture into the caller's arena memory instead
 * of a fresh heap block. Copies at most cap bytes, deactivates the
 * capture and resets the ring exactly like redirect_take, but the
 * caller owns dst so a pipeline stage assembles its output with one
 * kmalloc instead of three. Reports the copied count in len_out;
 * 0 with len 0 on empty capture or overflow. */

unsigned long redirect_take_into(char *dst, unsigned long cap,
        unsigned long *len_out) {
    unsigned long n;
    unsigned long i;
    redir_active = 0;
    if (len_out) *len_out = 0;
    if (redir_overflow || redir_len == 0) { redir_len = 0; return 0; }
    n = redir_len < cap ? redir_len : cap;
    if (dst) {
        for (i = 0; i < n; i++) dst[i] = redir_buf[i];
    }
    if (len_out) *len_out = n;
    redir_len = 0;
    return n;
}

/** Docstring: Drop the capture without any allocation. The ring keeps
 * its backing block for the next Ctrl+R / Ctrl+L build, so repeated
 * toolchain runs reuse one persistent bump buffer instead of churning
 * the heap. */

void redirect_discard(void) {
    redir_active = 0;
    redir_len = 0;
}

spinlock_t console_lock = SPINLOCK_INIT;

void vga_putc(char c) {
    int locked = spin_trylock(&console_lock);
    if (redirect_putc(c)) { if (locked) spin_unlock(&console_lock); return; }
    serial_putc(c);
    if (vga_fb_active) {
        if (c == '\n') serial_putc('\r');
        vga_fb_putc_term(c);
        if (locked) spin_unlock(&console_lock);
        return;
    }
    if (vga_mode_is_active()) {
        if (c == '\n') serial_putc('\r');
        if (locked) spin_unlock(&console_lock);
        return;
    }
    if (c == '\n') { serial_putc('\r'); vga_newline(); vga_set_cursor(vga_x, vga_y); if (locked) spin_unlock(&console_lock); return; }
    if (c == '\r') { vga_x = 0; vga_set_cursor(vga_x, vga_y); if (locked) spin_unlock(&console_lock); return; }
    if (c == '\t') {
        int spaces = 8 - (vga_x & 7);
        while (spaces--) vga_raw_space();
        vga_set_cursor(vga_x, vga_y);
        if (locked) spin_unlock(&console_lock);
        return;
    }
    if (c == '\b') {
        if (vga_x > 0) {
            vga_x--;
            unsigned off = vga_offset(vga_x, vga_y);
            VGA_BASE[off] = ' ';
            VGA_BASE[off + 1] = vga_color;
            vga_set_cursor(vga_x, vga_y);
        }
        if (locked) spin_unlock(&console_lock);
        return;
    }
    unsigned off = vga_offset(vga_x, vga_y);
    VGA_BASE[off]     = c;
    VGA_BASE[off + 1] = vga_color;
    vga_x++;
    if (vga_x >= VGA_COLS) vga_newline();

void vga_puts(const char *s) {
    while (*s) vga_putc(*s++);
}

