#define SWAP_MAGIC         0x53574150

static unsigned char *swap_buf_raw = 0;
static unsigned char *swap_buf_cmp = 0;

/** Docstring: Lazily own both scratch buffers. Returns 0 on OOM. */

static int swap_ensure(void)
{
    if (!swap_buf_raw) {
        swap_buf_raw = (unsigned char *)kmalloc(SWAP_CHUNK_RAW);
        if (!swap_buf_raw) return 0;
    }
    if (!swap_buf_cmp) {
        swap_buf_cmp = (unsigned char *)kmalloc(SWAP_CHUNK_CMP);
        if (!swap_buf_cmp) return 0;
    }
    return 1;
}

static unsigned long swap_lba(void) {
    unsigned int total = ide_total_sectors();
    if (total <= SWAP_MAX_SECTORS) return 0;
    return (unsigned long)(total - SWAP_MAX_SECTORS);
}

int swap_out(unsigned long window_sz) {
    unsigned long slba = swap_lba();
    if (!slba) return 0;
    if (!swap_ensure()) return 0;
    unsigned long nchunks = (window_sz + SWAP_CHUNK_RAW - 1) / SWAP_CHUNK_RAW;
    if (nchunks * SWAP_CHUNK_SECTORS + SWAP_HDR_SECTORS > SWAP_MAX_SECTORS)
        return 0;

    unsigned long data_lba = slba;
    for (unsigned long i = 0; i < nchunks; i++) {
        unsigned long off = i * SWAP_CHUNK_RAW;
        unsigned long raw_sz = window_sz - off;
        if (raw_sz > SWAP_CHUNK_RAW) raw_sz = SWAP_CHUNK_RAW;

        kmemcpy(swap_buf_raw, (void *)(USER_LOAD_BASE + off), raw_sz);
        if (raw_sz < SWAP_CHUNK_RAW)
            kmemset(swap_buf_raw + raw_sz, 0, SWAP_CHUNK_RAW - raw_sz);

        int csz = LZ4_compress_default((const char *)swap_buf_raw,
                    (char *)swap_buf_cmp + 4,
                    (int)SWAP_CHUNK_RAW, (int)(SWAP_CHUNK_CMP - 4));
        unsigned int disk_csz;
        if (csz > 0 && (unsigned long)csz < raw_sz) {
            disk_csz = (unsigned int)csz;
        } else {
            disk_csz = 0;
            kmemcpy(swap_buf_cmp + 4, swap_buf_raw, raw_sz);
        }
        *(unsigned int *)swap_buf_cmp = disk_csz;

        unsigned long total = 4 + (disk_csz ? disk_csz : raw_sz);
        unsigned long sects = (total + IDE_SECTOR_SIZE - 1) / IDE_SECTOR_SIZE;
        if (ide_write_sectors((unsigned int)data_lba, (unsigned int)sects,
                              swap_buf_cmp) < 0)
            return 0;
        data_lba += sects;
    }

    unsigned long hdr_lba = slba + SWAP_MAX_SECTORS - SWAP_HDR_SEC

int swap_in(void) {
    unsigned long slba = swap_lba();
    if (!slba) return 0;
    if (!swap_ensure()) return 0;

    unsigned long hdr_lba = slba + SWAP_MAX_SECTORS - SWAP_HDR_SECTORS;
    unsigned int hdr[3];
    if (ide_read_sectors((unsigned int)hdr_lba, SWAP_HDR_SECTORS, hdr) < 0)
        return 0;
    if (hdr[0] != SWAP_MAGIC) return 0;
    unsigned long window_sz = hdr[1];
    unsigned long nchunks   = hdr[2];

    unsigned long data_lba = slba;
    unsigned long dst = USER_LOAD_BASE;
    for (unsigned long i = 0; i < nchunks; i++) {
        if (ide_read_sectors((unsigned int)data_lba, SWAP_CHUNK_SECTORS,
                             swap_buf_cmp) < 0)
            return 0;
        unsigned int csz = *(unsigned int *)swap_buf_cmp;

        unsigned long raw_sz = window_sz - (dst - USER_LOAD_BASE);
        if (raw_sz > SWAP_CHUNK_RAW) raw_sz = SWAP_CHUNK_RAW;

        if (csz) {
            int dsz = LZ4_decompress_safe((const char *)swap_buf_cmp + 4,
                        (char *)swap_buf_raw, (int)csz, (int)SWAP_CHUNK_RAW);
            if (dsz < 0 || (unsigned long)dsz != raw_sz)
                return 0;
        } else {
            kmemcpy(swap_buf_raw, swap_buf_cmp + 4, raw_sz);
        }
        kmemcpy((void *)dst, swap_buf_raw, raw_sz);
        dst += raw_sz;
        data_lba += SWAP_CHUNK_SECTORS;
    }
    return 1;
}

static void panic_hex(unsigned long v, int digits) {
    static const char d[] = "0123456789abcdef";
    int i;
    for (i = digits - 1; i >= 0; i--)
        serial_putc(d[(v >> (i * 4)) & 0xF]);
}

static void panic_fb_puts(const char *s) {
    if (vga_fb_active) {
        while (*s) vga_fb_putc_term(*s++);
        return;
    }
    if (!vga_mode_is_active()) {
        static int row = 0;
        int col = 0;
        while (*s && row < VGA_ROWS) {
            unsigned off;
            if (*s == '\n') {
                row++;
                col = 0;
                s++;
                continue;
            }
            if (col >= VGA_COLS) {
                row++;
                col = 0;
                continue;
            }
            off = (unsigned)(row * VGA_COLS + col) * 2u;
            VGA_BASE[off] = *s;
            VGA_BASE[off + 1] = (char)0x4F;
            col++;
            s++;
        }
        if (row < VGA_ROWS) row++;
    }
}

static void panic_fb_hex(unsigned long v, int digits) {
    static const char d[] = "0123456789abcdef";
    char buf[16];
    int i;
    for (i = 0; i < digits && i < 16; i++)
        buf[i] = d[(v >> ((digits - 1 - i) * 4)) & 0xF];
    buf[i] = 0;
    panic_fb_puts(buf);
}

/** Docstring: Predicate behind the backtrace walk: canonical low half
 * and inside a readable range (kernel image, kernel heap or the user
 * window). Anything else stops the chain instead of nesting a fault. */
static int panic_frame_valid(unsigned long a) {
    if (a >= 0x0000800000000000UL)
        return 0;
    /* Low stacks: the shell boot stack and the syscall kernel stack
     * live below the kernel link base (identity mapped RAM). */
    if (a >= 0x80000UL && a < 0x100000UL)
        return 1;
    if (a >= 0x100000UL && a < 0x1000000UL)
        return 1;
    if (a >= (unsigned long)HEAP_BASE &&
            a < (unsigned long)HEAP_BASE + (unsigned long)HEAP_SIZE)
        return 1;
    if (a >= (unsigned long)USER_LOAD_BASE && a < (unsigned long)USER_LOAD_END)
        return 1;
    return 0;
}

/** Docstring: Paint the panic screen for an unrecoverable fault and
 * halt when asked. vector/err/rip/rsp come from the trap frame, rbp is
 * the faulting frame pointer. halt != 0 ends in hlt (real faults);
 * halt == 0 returns (the `panic` builtin demo). Re-entry halts
 * silently: the banner path itself faulted, nothing more can print. */

void panic_screen(unsigned long vector, unsigned long err,
        unsigned long rip, unsigned long rsp, unsigned long rbp, int halt) {
    unsigned long bt[PANIC_BT_MAX];
    int nbt, i;
    if (panic_entered) {
        for (;;) __asm__ volatile("hlt");
    }
    panic_entered = 1;
    nbt = panic_backtrace(rbp, panic_frame_valid, bt, PANIC_BT_MAX);
    serial_puts("panic: vector=");
    panic_hex(vector, 2);
    serial_puts(" err=");
    panic_hex(err, 8);
    serial_puts(" rip=");
    panic_hex(rip, 16);
    serial_puts(" rsp=");
    panic_hex(rsp, 16);
    serial_puts(" bt=");
    for (i = 0; i < nbt; i++) {
        serial_putc(' ');
        panic_hex(bt[i], 16);
    }
    if (nbt == 0)
        serial_puts(" <empty>");
    serial_puts("\n");
    panic_fb_puts("\n*** KERNEL PANIC ***\nvector=");
    panic_fb_hex(vector, 2);
    panic_fb_puts(" err=");
    panic_fb_hex(err, 8);
    panic_fb_puts("\nrip=");
    panic_fb_hex(rip, 16);
    panic_fb_puts("\nrsp=");
    panic_fb_hex(rsp, 16);
    panic_fb_puts("\nbt=");
    for (i = 0; i < nbt; i++) {
        panic_fb_puts(" ");
        panic_fb_hex(bt[i], 16);
    }
    if (nbt == 0)
        panic_fb_puts(" <empty>");

static int rq_cpu_valid(int cpu) {
    return cpu >= 0 && cpu < MAX_CPUS && cpu < cpu_count;
}

/** Docstring: Clear every ring and counter. Called once from sched_init. */

void rq_init(void) {
    int c;
    int i;
    for (c = 0; c < MAX_CPUS; c++) {
        spin_init(&rqueues[c].lock);
        for (i = 0; i < RQ_DEPTH; i++)
            rqueues[c].ring[i] = WQ_NONE_HINT;
        rqueues[c].head = 0;
        rqueues[c].count = 0;
        rqueues[c].hits = 0;
        rqueues[c].steals = 0;
        rqueues[c].drops = 0;
        rqueues[c].polls = 0;
    }
}

/** Docstring: Record pid as READY work for cpu.
 *
 * Lossy by contract: a full ring drops the hint and counts the drop. The
 * global scan remains the fallback, so a drop costs one rescan period of
 * latency at most, never correctness. Pids outside the table are refused.
 */

void rq_enqueue(int cpu, int pid) {
    irqflags_t flags;
    int slot;
    if (!rq_cpu_valid(cpu))
        return;
    if (pid <= 0 || pid >= MAX_PROCS)
        return;
    spin_lock_irqsave(&rqueues[cpu].lock, &flags);
    if (rqueues[cpu].count >= RQ_DEPTH) {
        rqueues[cpu].drops++;
        spin_unlock_irqrestore(&rqueues[cpu].lock, flags);
        return;
    }
    slot = (rqueues[cpu].head + rqueues[cpu].count) % RQ_DEPTH;
    rqueues[cpu].ring[slot] = pid;
    rqueues[cpu].count++;
    spin_unlock_irqrestore(&rqueues[cpu].lock, flags);
}

/** Docstring: Pop one hint from the local ring, WQ_NONE_HINT when empty. */

int rq_pop_local(int cpu) {
    irqflags_t flags;
    int pid;
    if (!rq_cpu_valid(cpu))
        return WQ_NONE_HINT;
    spin_lock_irqsave(&rqueues[cpu].lock, &flags);
    if (rqueues[cpu].count <= 0) {
        spin_unlock_irqrestore(&rqueues[cpu].lock, flags);
        return WQ_NONE_HINT;
    }
    pid = rqueues[cpu].ring[rqueues[cpu].head];
    rqueues[cpu].ring[rqueues[cpu].head] = WQ_NONE_HINT;
    rqueues[cpu].head = (rqueues[cpu].head + 1) % RQ_DEPTH;
    rqueues[cpu].count--;
    rqueues[cpu].hits++;
    spin_unlock_irqrestore(&rqueues[cpu].lock, flags);
    return pid;
}

/** Docstring: Non-blocking steal of one hint from another CPU's ring.
 *
 * Tries every remote ring once with spin_trylock and returns the first
 * hint found, reporting the donor through from_cpu. Rings that are busy
 * are skipped, never waited on. Returns WQ_NONE_HINT when nothing could
 * be stolen without blocking. The thief's steal counter is owner-written
 * but updated under the donor's lock, so it uses an atomic add (the same
 * pattern as smp_dispatches) instead of relying on the donor's lock.
 */

int rq_steal_once(int self_cpu, int *from_cpu) {
    int c;
    for (c = 0; c < cpu_count && c < MAX_CPUS; c++) {
        int pid;
        if (c == self_cpu)
            continue;
        if (!spin_trylock(&rqueues[c].lock))
            continue;
        if (rqueues[c].count <= 0) {
            spin_unlock(&rqueues[c].lock);
            continue;
        }
        pid = rqueues[c].ring[rqueues[c].head];
        rqueues[c].ring[rqueues[c].head] = WQ_NONE_HINT;
        rqueues[c].head = (rqueues[c].head + 1) % RQ_DEPTH;
        rqueues[c].count--;
        __sync_fetch_and_add(&rqueues[self_cpu].steals, 1);
        spin_unlock(&rqueues[c].lock);
        if (from_cpu)
            *from_cpu = c;
        return pid;
    }
    return WQ_NONE_HINT;
}

/** Docstring: True when cpu holds no hint. Lock-protected peek. */

int rq_empty(int cpu) {
    irqflags_t flags;
    int empty;
    if (!rq_cpu_valid(cpu))
        return 1;
    spin_lock_irqsave(&rqueues[cpu].lock, &flags);
    empty = (rqueues[cpu].count <= 0);
    spin_unlock_irqrestore(&rqueues[cpu].lock, flags);
    return empty;
}

/** Docstring: Count an unsuccessful claim poll for the rescan schedule. */

void rq_note_poll(int cpu) {
    irqflags_t flags;
    if (!rq_cpu_valid(cpu))
        return;
    spin_lock_irqsave(&rqueues[cpu].lock, &flags);
    rqueues[cpu].polls++;
    spin_unlock_irqrestore(&rqueues[cpu].lock, flags);
}

/** Docstring: True every RQ_RESCAN_PERIOD polls, bounding hint staleness. */

int rq_should_rescan(int cpu) {
    irqflags_t flags;
    int due = 0;
    if (!rq_cpu_valid(cpu))
        return 1;
    spin_lock_irqsave(&rqueues[cpu].lock, &flags);
    if (rqueues[cpu].polls >= RQ_RESCAN_PERIOD) {
        rqueues[cpu].polls = 0;
        due = 1;
    }
    spin_unlock_irqrestore(&rqueues[cpu].lock, flags);
    return due;
}

/** Docstring: Snapshot hits, steals and drops for diagnostics. */

void rq_stats(int cpu, unsigned long *hits, unsigned long *steals,
              unsigned long *drops) {
    irqflags_t flags;
    if (!rq_cpu_valid(cpu))
        return;
    spin_lock_irqsave(&rqueues[cpu].lock, &flags);
    if (hits)
        *hits = rqueues[cpu].hits;
    if (steals)
        *steals = rqueues[cpu].steals;
    if (drops)
        *drops = rqueues[cpu].drops;
    spin_unlock_irqrestore(&rqueues[cpu].lock, flags);
}

static void putc_buf(char c, void *ctx, int *written) {
