static int smp_any_ap_idle(void) {
    int c;
    for (c = 1; c < cpu_count && c < MAX_CPUS; c++)
        if (cpus[c].cur_pid < 0) return 1;
    return 0;
}

/* Counts timer ticks that arrived with an unusable GS base (a ring-0
 * context running with a user/stale GS, so this_cpu() points outside
 * cpus[]).  Reported by the `smp` builtin; nonzero means a GS-lifecycle
 * window fired (see cpu_or_null). */
volatile unsigned smp_dbg_bad_gs;
/* Observability counters for `irqstat`: per-source ISR arrivals. The
 * timer slot reuses sys_ticks (100 Hz PIT + BSP IPI broadcast); kbd and
 * mouse count IRQ1/IRQ12 deliveries, sb16 counts IRQ5 completions.
 * Increment-only, read without a lock (single-word, torn reads impossible
 * on x86 for aligned words; worst case the shell prints a value one tick
 * stale, never a corrupt one). */
volatile unsigned long isr_cnt_kbd;
volatile unsigned long isr_cnt_mouse;
volatile unsigned long isr_cnt_sb16;

/* RLIMIT_CPU accounting: called once per timer tick for the running
 * proc on each CPU. Sets cpu_kill_pending when the cap is reached; the
 * actual kill happens at the next scheduling edge (preempt path for
 * pid > 0, syscall-dispatch check for pid 0), never mid-ISR. */
void rlimit_cpu_tick(int pid) {
    proc_t *p;
    if (pid < 0 || pid >= MAX_PROCS) return;
    p = &procs[pid];
    if (p->state != PROC_RUNNING && p->state != PROC_READY) return;
    p->cpu_ticks++;
    if (p->rl_cpu_max && p->cpu_ticks >= p->rl_cpu_max)
        p->cpu_kill_pending = 1;
}

int rlimit_cpu_exceeded(int pid) {
    if (pid < 0 || pid >= MAX_PROCS) return 0;
    if (procs[pid].state == PROC_FREE) return 0;
    return procs[pid].cpu_kill_pending;
}

/* Validate the GS-derived per-CPU pointer before trusting it.  A ring-0
 * context running with a user (or otherwise stale) GS base makes
 * this_cpu() read garbage — typically the IVT at linear 0, which is
 * mapped, so the read itself succeeds and the first field dereference
 * faults with #GP instead of failing safe.  Returns NULL unless the
 * pointer falls inside cpus[]. */
static cpu_t *cpu_or_null(void) {
    unsigned long v;
    __asm__ volatile("mov %%gs:0, %0" : "=r"(v));
