    tgt->exit_code = -1;
    tgt->state = PROC_ZOMBIE;
    tgt->exited = 1;
    if (tgt->parent_pid >= 0) {
        proc_t *par = proc_get(tgt->parent_pid);
        if (par && par->state == PROC_BLOCKED)
            par->state = PROC_READY;
    }
    spin_unlock(&sched_lock);
    return 0;
}

void sched_init(void) {
    int c;
    kmemset(procs, 0, sizeof(procs));
    kmemset(cpus, 0, sizeof(cpus));
    kmemset(ap_idle_proc, 0, sizeof(ap_idle_proc));
    proc_count = 1;

    /* Paint the legacy 32 KB syscall stack before anything can run on

 * it (SPAWN/exec point proc 0 here transiently); the pool slots
 * paint at alloc. kstack_report() reads both. */
kstack_paint(SYS_KSTK_TOP, SYS_KSTK_TOP - SYS_KSTK_BASE);

/* Per-CPU idle contexts: pid -1 marks them as never-pickable; a
 * state other than PROC_READY keeps every scan away.  The AP fills
 * in its own entry in smp_ap_entry before its first dispatch.
 * cr3 must be the kernel tables on every CPU: switch_to loads
 * next->ctx.cr3 unconditionally, so a zero would wipe the page
 * tables the first time schedule() parks a finished process.
 * rip/rsp point at a private idle stack so a park into a virgin
 * idle context re-enters the idle loop instead of jumping to 0. */
{
    unsigned long cr3 = read_cr3();
    for (c = 0; c < MAX_CPUS; c++) {
        ap_idle_proc[c].pid = -1;
        ap_idle_proc[c].state = PROC_BLOCKED;
        ap_idle_proc[c].parent_pid = -1;
        ap_idle_proc[c].ctx.cr3 = cr3;
        ap_idle_proc[c].ctx.rip = (uint64_t)smp_ap_idle_loop;
        ap_idle_proc[c].ctx.rsp =
            (uint64_t)&ap_idle_stack[c][sizeof(ap_idle_stack[0])];
        ap_idle_proc[c].ctx.rflags = 0x202;
    }
}

/* Initialize BSP (cpu 0) per-CPU state */
cpus[0].self = &cpus[0];
cpus[0].cpu_id = BOOT_CPU;
cpus[0].cur_pid = 0;
cpus[0].is_bsp = 1;
cpus[0].lapic_id = 0;
cpus[0].syscall_kstack = SYS_KSTK_TOP;

/* Set GS base so this_cpu() works from the BSP */
wrmsr(MSR_GSBASE, (unsigned long)&cpus[0]);
/* Seed the SYSCALL swap tar

 * park (the save path skips a null area). */
procs[0].fpu_save = fpu_alloc_clean();
/* The legacy single-window VMA view: pid 0 and every k_exec_user run
 * share it, so the historical path behaves exactly as before. */
vma_ctx_init(&vma_legacy, 0);
vma_ctx_bind(&vma_legacy);
procs[0].vma = &vma_legacy;

/* IDT and TSS FIRST: pic_init unmasks IRQ0/1/12, and the PIT starts
 * firing the moment pit_init runs — an IRQ delivered with the IDT

     * still zeroed (kmemset happens inside idt_init) faults through a
     * null gate.  Handlers for 32/33/44 are safe pre-mouse-init. */
    idt_init();
    tss_init();
    futex_init();
    rq_init();
    rcu_init();
    tick_reset();
    tick_register_audio(sched_tick_audio, 0);
    /* MINFO sleep queue plus its per-tick waker: without the waker a
     * timed sleep would never end, so init takes the registration
     * result and sel 6 fails closed when it is missing. */
    minfo_sleep_init(tick_register_audio(minfo_tick_wake, 0) == 0);
    tick_register_desktop(sched_tick_desktop, 0);
    tick_register_usb(sched_tick_usb, 0);
    pic_init();
    pit_init();
    mouse_hw_init();
    __asm__ volatile("sti");
    sched_ready = 1;
}

#define SCROLLBACK_ROWS 4096

static char *sb_ring;
static int   sb_head, sb_count, sb_inited;

void sb_init(void) {
    sb_ring = (char *)kmalloc((unsigned long)SCROLLBACK_ROWS * VGA_COLS);
    sb_inited = sb_ring ? 1 : -1;
    sb_head = sb_count = 0;
}

void sb_capture_row0(void) {
    if (sb_inited == 0) sb_init();
    if (sb_inited != 1) return;
    int idx = (sb_head + sb_count) % SCROLLBACK_ROWS;
    /* Row 0 character cells: VGA_BASE[x*2] for each column. */
    for (int x = 0; x < VGA_COLS; x++)
        sb_ring[(unsigned long)idx * VGA_COLS + x] = VGA_BASE[x * 2];
    if (sb_count < SCROLLBACK_ROWS) sb_count++;
    else sb_head = (sb_head + 1) % SCROLLBACK_ROWS;
}

void sb_reset(void) {
    if (sb_ring) { sb_head = sb_count = 0; }
}

char sb_get_char(int row, int col) {
    int idx = (sb_head + row) % SCROLLBACK_ROWS;
    return sb_ring[(unsigned long)idx * VGA_COLS + col];
}

void serial_init(void) {
    outb(COM1 + 1, 0x00);
    outb(COM1 + 3, 0x80);
    outb(COM1 + 0, 0x01);
    outb(COM1 + 1, 0x00);
    outb(COM1 + 3, 0x03);
    outb(COM1 + 2, 0xC7);
    outb(COM1 + 4, 0x0B);
}

void serial_putc(char c) {
    while (!serial_tx_ready());
    outb(COM1, (unsigned char)c);
}

