unsigned long kstrlen(const char *s) {
    const char *p = s;
    while (*p) p++;
    return (unsigned long)(p - s);
}

char *kstrcpy(char *dst, const char *src) {
    char *d = dst;
    while ((*d++ = *src++));
    return dst;
}

char *kstrncpy(char *dst, const char *src, unsigned long n) {
    char *d = dst;
    while (n-- && (*d++ = *src++));
    return dst;
}

char *kstrncat(char *dst, const char *src, unsigned long n) {
    char *d = dst;
    while (*d) d++;
    while (n-- && *src) *d++ = *src++;
    *d = 0;
    return dst;
}

int kstrcmp(const char *a, const char *b) {
    while (*a && *a == *b) { a++; b++; }
    return (unsigned char)*a - (unsigned char)*b;
}

int kstrncmp(const char *a, const char *b, unsigned long n) {
    while (n-- && *a && *a == *b) { a++; b++; }
    return n == (unsigned long)-1 ? 0 : (unsigned char)*a - (unsigned char)*b;
}

char *kstrchr(const char *s, int c) {
    while (*s) { if (*s == (char)c) return (char *)s; s++; }
    return 0;
}

char *kstrstr(const char *hay, const char *ndl) {
    unsigned long nl = kstrlen(ndl);
    if (nl == 0) return (char *)hay;
    while (*hay) {
        if (kstrncmp(hay, ndl, nl) == 0) return (char *)hay;
        hay++;
    }
    return 0;
}

void *kmemcpy(void *dst, const void *src, unsigned long n) {
    char *d = dst;
    const char *s = src;
    while (n--) *d++ = *s++;
    return dst;
}

void *kmemset(void *dst, int c, unsigned long n) {
    char *d = dst;
    while (n--) *d++ = (char)c;
    return dst;
}

int kmemcmp(const void *a, const void *b, unsigned long n) {
    const unsigned char *pa = a, *pb = b;
    while (n--) { if (*pa != *pb) return *pa - *pb; pa++; pb++; }
    return 0;
}

void *kmemmove(void *dst, const void *src, unsigned long n) {
    char *d = dst;
    const char *s = src;
    if (d < s) { while (n--) *d++ = *s++; }
    else       { d += n; s += n; while (n--) *--d = *--s; }
    return dst;
}

long katol(const char *s) {
    long v = 0, sign = 1;
    while (*s == ' ') s++;
    if (*s == '-') { sign = -1; s++; }
    else if (*s == '+') s++;
    while (*s >= '0' && *s <= '9') { v = v * 10 + (*s - '0'); s++; }
    return v * sign;
}

void k_register_symbol(const char *name, void *addr) {
    if (ksym_count < KSYM_MAX) {
        ksym_table[ksym_count].name = name;
        ksym_table[ksym_count].addr = addr;
        ksym_count++;
    }
}

void *ksym_resolve(const char *name) {
    int i;
    for (i = 0; i < ksym_count; i++) {
        if (kstrcmp(ksym_table[i].name, name) == 0)
            return ksym_table[i].addr;
    }
    return 0;
}

/* ================================================================
 *  Program registry — maps names to ET_REL / ET_EXEC entry points
 * ================================================================ */

KProg kprog_table[KPROG_MAX];
int   kprog_count;

KProg *kprog_slot(const char *name) {
    int i;
    for (i = 0; i < kprog_count; i++)
        if (kstrcmp(kprog_table[i].name, name) == 0) return &kprog_table[i];
    if (kprog_count < KPROG_MAX) return &kprog_table[kprog_count++];
    return 0;
}

KProg *kprog_lookup(const char *name) {
    int i;
    for (i = 0; i < kprog_count; i++)
        if (kstrcmp(kprog_table[i].name, name) == 0) return &kprog_table[i];
    return 0;
}

void k_register_program(const char *name, prog_entry_t entry) {
    KProg *p = kprog_slot(name);
    if (!p) return;
    kstrncpy(p->name, name, sizeof(p->name) - 1);
    p->name[sizeof(p->name) - 1] = 0;
    p->entry = entry; p->proc_entry = 0; p->is_proc = 0;
}

void k_register_process(const char *name, void *proc_entry) {
    KProg *p = kprog_slot(name);
    if (!p) return;
    kstrncpy(p->name, name, sizeof(p->name) - 1);
    p->name[sizeof(p->name) - 1] = 0;
    p->entry = 0; p->proc_entry = proc_entry; p->is_proc = 1;
}

int k_spawn(const char *name, int argc, char **argv) {
    int i;
    for (i = 0; i < kprog_count; i++) {
        if (kstrcmp(kprog_table[i].name, name) == 0) {
            if (kprog_table[i].is_proc)
                return k_exec_user(kprog_table[i].proc_entry, argc, argv);
            return k_run_rel(kprog_table[i].entry, argc, argv);
        }
    }
    return -1;
}

void wq_init(wait_queue_t *q) {
    spin_init(&q->lock);
    q->head = WQ_NONE;
    q->tail = WQ_NONE;
}

void sleep_on(wait_queue_t *q) {
    irqflags_t flags;
    spin_lock_irqsave(&q->lock, &flags);
    proc_t *cur = proc_get(current_pid);
    if (!cur) {
        spin_unlock_irqrestore(&q->lock, flags);
        return;
    }
    cur->state = PROC_BLOCKED;
    cur->wq_next = WQ_NONE;
    if (q->head == WQ_NONE) {
        q->head = cur->pid;
        q->tail = cur->pid;
    } else {
        procs[q->tail].wq_next = cur->pid;
        q->tail = cur->pid;
    }
    spin_unlock_irqrestore(&q->lock, flags);
    schedule();
}

int wake_up(wait_queue_t *q) {
    irqflags_t flags;
    spin_lock_irqsave(&q->lock, &flags);
    if (q->head == WQ_NONE) {
        spin_unlock_irqrestore(&q->lock, flags);
        return WQ_NONE;
    }
    int pid = q->head;
    q->head = procs[pid].wq_next;
    if (q->head == WQ_NONE) q->tail = WQ_NONE;
    procs[pid].wq_next = WQ_NONE;
    if (procs[pid].state == PROC_BLOCKED) procs[pid].state = PROC_READY;
    spin_unlock_irqrestore(&q->lock, flags);
    return pid;
}

int wake_up_all(wait_queue_t *q) {
    int n = 0;
    while (wake_up(q) != WQ_NONE) n++;
    return n;
}

void mutex_init(mutex_t *m) {
    spin_init(&m->guard);
    m->locked = 0;
    m->owner = WQ_NONE;
    wq_init(&m->waiters);
}

/* Priority-inheritance state, parallel to procs[] (proc_t size is frozen
 * by the syscall-entry asm). pi_blocked_on stores owner pid + 1 so that
 * zero-initialized memory means "blocks on nobody". All updates happen
 * with the mutex guard held, which already serializes lock/unlock paths;
 * pi_set_base takes the guard of no mutex and races a concurrent boost by
 * at most one stale read, resolved on the next lock/unlock recompute. */
static int pi_base[MAX_PROCS];
static int pi_eff[MAX_PROCS];
static int pi_blocked_on[MAX_PROCS];

static int pi_valid(int pid) {
    return pid >= 0 && pid < MAX_PROCS;
}

static void pi_recompute(int pid);

void pi_set_base(int pid, int prio) {
    if (!pi_valid(pid) || prio < 0) return;
    pi_base[pid] = prio;
    /* Recompute instead of max: lowering a base while donated keeps the
     * live donation, and a fresh assignment never inherits a stale boost
     * from an earlier test or a dead waiter. */
    pi_recompute(pid);
}

int pi_get_eff(int pid) {
    if (!pi_valid(pid)) return -1;
    return pi_eff[pid];
}

static void pi_recompute(int pid) {
    int p, best;
    if (!pi_valid(pid)) return;
    best = pi_base[pid];
    for (p = 0; p < MAX_PROCS; p++) {
        if (pi_blocked_on[p] == pid + 1 && pi_eff[p] > best)
            best = pi_eff[p];
    }
    pi_eff[pid] = best;
}

static void pi_boost(int waiter, int owner) {
    int depth, cur, next;
    if (!pi_valid(waiter) || !pi_valid(owner)) return;
    cur = waiter;
    next = owner;
    for (depth = 0; depth < MAX_PROCS; depth++) {
        if (pi_eff[next] >= pi_eff[cur]) break;
        pi_eff[next] = pi_eff[cur];
        if (!pi_blocked_on[next]) break;
        cur = next;
        next = pi_blocked_on[next] - 1;
        if (!pi_valid(next)) break;
    }
}

/* Record that waiter blocks on this mutex's holder and donate its
 * priority along the chain. Guard must be held. Split out so the host
 * suite drives contention deterministically (a real mutex_lock contender
 * would spin on the host stub scheduler). */
void mutex_note_waiter(mutex_t *m, int waiter) {
    if (pi_valid(waiter) && pi_valid(m->owner)) {
        pi_blocked_on[waiter] = m->owner + 1;
        pi_boost(waiter, m->owner);
    }
}

void mutex_lock(mutex_t *m) {
    for (;;) {
        irqflags_t flags;
        int me;
        spin_lock_irqsave(&m->guard, &flags);
        if (!m->locked) {
            m->locked = 1;
            m->owner = current_pid;
            me = current_pid;
            spin_unlock_irqrestore(&m->guard, flags);
            if (pi_valid(me)) pi_blocked_on[me] = 0;
            return;
        }
        me = current_pid;
        mutex_note_waiter(m, me);
        spin_unlock_irqrestore(&m->guard, flags);
        sleep_on(&m->waiters);
    }
}

int mutex_trylock(mutex_t *m) {
    irqflags_t flags;
    int ok;
    spin_lock_irqsave(&m->guard, &flags);
    if (m->locked) {
        ok = -1;
    } else {
        m->locked = 1;
        m->owner = current_pid;
        ok = 0;
    }
    spin_unlock_irqrestore(&m->guard, flags);
    if (ok == 0 && pi_valid(current_pid)) pi_blocked_on[current_pid] = 0;
    return ok;
}

void mutex_unlock(mutex_t *m) {
    irqflags_t flags;
    int old, q;
    spin_lock_irqsave(&m->guard, &flags);
    old = m->owner;
    m->locked = 0;
    m->owner = WQ_NONE;
    /* Queued waiters stop blocking on the old owner: they retry and
     * re-establish (or clear) their edge on the next acquisition loop,
     * so no stale donation survives the release. */
    q = m->waiters.head;
    while (q != WQ_NONE && pi_valid(q)) {
        int next = procs[q].wq_next;
        pi_blocked_on[q] = 0;
        q = next;
    }
    spin_unlock_irqrestore(&m->guard, flags);
    if (pi_valid(old)) pi_recompute(old);
    wake_up(&m->waiters);
}

void sem_init(sem_t *s, int value) {
    spin_init(&s->guard);
    s->count = value < 0 ? 0 : value;
    wq_init(&s->waiters);
}

void sem_wait(sem_t *s) {
    for (;;) {
        irqflags_t flags;
        spin_lock_irqsave(&s->guard, &flags);
        if (s->count > 0) {
            s->count--;
            spin_unlock_irqrestore(&s->guard, flags);
            return;
        }
        spin_unlock_irqrestore(&s->guard, flags);
        sleep_on(&s->waiters);
    }
}

void sem_post(sem_t *s) {
    irqflags_t flags;
    spin_lock_irqsave(&s->guard, &flags);
    s->count++;
    spin_unlock_irqrestore(&s->guard, flags);
    wake_up(&s->waiters);
}

void cond_init(cond_t *c) {
    wq_init(&c->waiters);
}

void cond_wait(cond_t *c, mutex_t *m) {
    mutex_unlock(m);
    sleep_on(&c->waiters);
    mutex_lock(m);
}

void cond_signal(cond_t *c) {
    wake_up(&c->waiters);
}

void cond_broadcast(cond_t *c) {
    wake_up_all(&c->waiters);
}

void rwlock_init(rwlock_t *rw) {
    spin_init(&rw->guard);
    rw->readers = 0;
    rw->writer = 0;
    wq_init(&rw->waiters);
}

void rwlock_read_lock(rwlock_t *rw) {
    for (;;) {
        irqflags_t flags;
        spin_lock_irqsave(&rw->guard, &flags);
        if (!rw->writer) {
            rw->readers++;
            spin_unlock_irqrestore(&rw->guard, flags);
            return;
        }
        spin_unlock_irqrestore(&rw->guard, flags);
        sleep_on(&rw->waiters);
    }
}

void rwlock_read_unlock(rwlock_t *rw) {
    irqflags_t flags;
    spin_lock_irqsave(&rw->guard, &flags);
    if (rw->readers > 0) rw->readers--;
    int wake = (rw->readers == 0);
    spin_unlock_irqrestore(&rw->guard, flags);
    if (wake) wake_up(&rw->waiters);
}

void rwlock_write_lock(rwlock_t *rw) {
    for (;;) {
        irqflags_t flags;
        spin_lock_irqsave(&rw->guard, &flags);
        if (!rw->writer && rw->readers == 0) {
            rw->writer = 1;
            spin_unlock_irqrestore(&rw->guard, flags);
            return;
        }
        spin_unlock_irqrestore(&rw->guard, flags);
        sleep_on(&rw->waiters);
    }
}

void rwlock_write_unlock(rwlock_t *rw) {
    irqflags_t flags;
    spin_lock_irqsave(&rw->guard, &flags);
    rw->writer = 0;
    spin_unlock_irqrestore(&rw->guard, flags);
    wake_up_all(&rw->waiters);
}

#define KFD_MAX 32

/* Root view for the shell and every pid without its own (pid 0, AP
 * idle): .bss-zeroed entries, never freed, so NULL proc->kfd and an
 * invalid current_pid degrade to the historical shared table. */
static kfd_view_t kfd_root;

/** Docstring: View owning the caller's fds: its own on isolated procs
 * and threads, the root on pid 0 and any pid without one. */

static kfd_view_t *kfd_view_current(void) {
    if (current_pid >= 1 && current_pid < MAX_PROCS
        && procs[current_pid].state != PROC_FREE
        && procs[current_pid].kfd)
        return procs[current_pid].kfd;
    return &kfd_root;
}

/** Docstring: Static root view (shell pid 0, pids without their own):
 * entries are the historical shared table, never freed. */

kfd_view_t *kfd_view_root(void) {
    return &kfd_root;
}

/* Guards g_brk/g_brk_limit/user_mmap_cur and the VMA trees against
 * concurrent brk/mmap/munmap syscalls from threads on different CPUs.
 * Lock order: sched_lock -> mm_lock (the scheduler takes mm_lock
 * inside sched_lock for the brk/mmap view switch; syscalls take
 * mm_lock alone).  Declared extern in the scheduler via sched.c. */
spinlock_t mm_lock = SPINLOCK_INIT;

/* Leaf lock for every view's membership plus KFILE refcounts (see the
 * KFILE contract in kernel.h). Every section is a few instructions:
 * scan, assign, clear, bump or drop. File IO itself always runs
 * outside it with a held reference instead, so a close racing a
 * read drops the view slot but never frees under the reader, and
 * two racing opens can never claim the same slot twice. */
spinlock_t fd_lock = SPINLOCK_INIT;

KFILE *kfd_get(int fd) {
    irqflags_t flags;
    KFILE *f = 0;
    kfd_view_t *v = kfd_view_current();
    spin_lock_irqsave(&fd_lock, &flags);
    if (fd >= 0 && fd < KFD_MAX && v->f[fd]) {
        f = v->f[fd];
        f->ref++;
    }
    spin_unlock_irqrestore(&fd_lock, flags);
    return f;
}

void kfd_put(KFILE *f) {
    irqflags_t flags;
    int drop = 0;
    if (!f) return;
    spin_lock_irqsave(&fd_lock, &flags);
    f->ref--;
    if (f->ref <= 0) drop = 1;
    spin_unlock_irqrestore(&fd_lock, flags);
    if (drop) kfclose(f);
}

/** Docstring: Count live entries in a view (fd accounting source). */

static int kfd_view_count(kfd_view_t *v) {
    int i, n = 0;
    if (!v) return 0;
    for (i = 0; i < KFD_MAX; i++) if (v->f[i]) n++;
    return n;
}

/** Docstring: Share the caller's view with a new thread (CLONE_FILES /
 * CLONE_VM): one view refcount bump, entries untouched. The child must
 * be unpublished (PROC_SWITCHING) so no other CPU can claim it mid-way. */
void kfd_view_share(proc_t *child) {
    irqflags_t flags;
    kfd_view_t *v = kfd_view_current();
    spin_lock_irqsave(&fd_lock, &flags);
    if (v != &kfd_root) v->ref++;
    spin_unlock_irqrestore(&fd_lock, flags);
    child->kfd = (v == &kfd_root) ? 0 : v;
    child->open_files = kfd_view_count(v);
}

/** Docstring: Copy a parent's view for an isolated child (fork, spawn):
 * a fresh heap view with one KFILE ref bump per live entry, so either
 * side closing never drops the other's handle. A NULL parent (or one
 * without its own view) copies the root. Returns 0 on OOM with the

 * child untouched (caller refuses fail-closed). */
int kfd_view_copy(proc_t *child, proc_t *parent) {
    irqflags_t flags;
    kfd_view_t *v = kfd_view_root();
    kfd_view_t *nv;
    int i;
    if (parent && parent->kfd) v = parent->kfd;
    nv = (kfd_view_t *)kmalloc(sizeof(kfd_view_t));
    if (!nv) return 0;
    for (i = 0; i < KFD_MAX; i++) nv->f[i] = 0;
    nv->cloexec = 0;
    nv->ref = 1;
    spin_lock_irqsave(&fd_lock, &flags);
    for (i = 0; i < KFD_MAX; i++) {
        nv->f[i] = v->f[i];
        if (nv->f[i]) nv->f[i]->ref++;
    }
    nv->cloexec = v->cloexec;
    spin_unlock_irqrestore(&fd_lock, flags);
    child->kfd = nv;
    child->open_files = kfd_view_count(nv);
    return 1;
}

/** Docstring: Release a reaped process's view: drop one view ref and,
 * at zero, one KFILE ref per live entry (closing what the last owner
 * held) plus the view itself. The root view is never freed. Idempotent

 * on NULL (already released or never owned). */
void kfd_view_release(proc_t *p) {
    irqflags_t flags;
    kfd_view_t *v;
    KFILE *drop[KFD_MAX];
    int i, ndrop = 0, free_view = 0;
    if (!p || !p->kfd) return;
    v = p->kfd;
    p->kfd = 0;
    p->open_files = 0;
    spin_lock_irqsave(&fd_lock, &flags);
    v->ref--;
    if (v->ref <= 0 && v != &kfd_root) {
        free_view = 1;
        for (i = 0; i < KFD_MAX; i++) {
            if (v->f[i]) {
                v->f[i]->ref--;
                if (v->f[i]->ref <= 0 && ndrop < KFD_MAX)
                    drop[ndrop++] = v->f[i];
                v->f[i] = 0;
            }
        }
    }
    spin_unlock_irqrestore(&fd_lock, flags);
    for (i = 0; i < ndrop; i++) kfclose(drop[i]);
    if (free_view) kfree(v);
}

/** Docstring: Close every CLOEXEC fd in the caller's own view (execve:
 * the image is replaced, marked descriptors must not survive). Runs on
 * the live view entries with the same ref discipline as close. */

void kfd_view_cloexec(void) {
    irqflags_t flags;
    kfd_view_t *v = kfd_view_current();
    KFILE *drop[KFD_MAX];
    unsigned mask;
    int i, ndrop = 0;
    proc_t *cp = (current_pid >= 0 && current_pid < MAX_PROCS)
        ? &procs[current_pid] : 0;
    spin_lock_irqsave(&fd_lock, &flags);
    mask = v->cloexec;
    v->cloexec = 0;
    for (i = 0; i < KFD_MAX && mask; i++) {
        if ((mask & (1u << (unsigned)i)) && v->f[i]) {
            KFILE *f = v->f[i];
            v->f[i] = 0;
            f->ref--;
            if (f->ref <= 0 && ndrop < KFD_MAX) drop[ndrop++] = f;
            if (cp && cp->open_files > 0) cp->open_files--;
        }
        mask &= ~(1u << (unsigned)i);
