    if (id == wm_focus) return 0;
    if ((user_program_active || shell_fg_active) && wm_focus == WM_FOCUS_GFX)
        serial_puts("wm: fg program owns input; use `run X &` so Alt-Tab splits input\n");
    if (wm_focus == WM_FOCUS_GFX && gfx_covers_screen())
        gfx_hidden = 1;
