int tls_x509_parse_pubkey(const unsigned char *der, unsigned len,
                          struct tls_pubkey *pk) {
    struct x509_cert cert;
    if (cert_parse(der, len, &cert) != 0) return -1;
    TLS_MEMCPY(pk, &cert.pk, sizeof(*pk));
    return 0;
