static void dmap_recenter(void) {
    int r, c;
    for (r = 0; r < dmap_h; r++)
        for (c = 0; c < dmap_w; c++)
            if (dmap_grid[r][c] == DMAP_PLAYER) {
                dmap_px = (float)c + 0.5f;
                dmap_py = (float)r + 0.5f;
            }
    dmap_angle = 0.0f;
