    (void)ud;
    if (e0)
        return;
    if (code == 0x1D) {
        dmap_ctrl_held = make;
        return;
    }
    if (!make || !dmap_ctrl_held)
        return;
    if (code == 0x13)
        dmap_run_requested = 1;
    else if (code == 0x2C)
        dmap_undo_requested = 1;
    else if (code == 0x15)
        dmap_redo_requested = 1;
}

