static long sys_doom_frame(void) {
    long ret;
    __asm__ volatile("syscall" : "=a"(ret) : "a"(MINIOS_SYS_GFX_PRESENT), "D"((long)MINIOS_GFX_BUF_GAME), "S"((long)0) : "rcx","r11","memory");
    return ret;
}

