//

boolean P_CheckMissileRange (mobj_t* actor)
{
    fixed_t	dist;

    if (! P_CheckSight (actor, actor->target) )
	return false;

    if ( actor->flags & MF_JUSTHIT )
    {
	// the target just hit the enemy,
	// so fight back!
	actor->flags &= ~MF_JUSTHIT;
	return true;
    }

    if (actor->reactiontime)
