static int player_collides(float x, float y, float z) {
    float r = 0.3f, h = 1.7f;
    int x0 = (int)floorf(x - r), x1 = (int)floorf(x + r);
    int y0 = (int)floorf(y - r), y1 = (int)floorf(y + r);
    int z0 = (int)floorf(z), z1 = (int)floorf(z + h - 0.05f);
    int ix, iy, iz;
    for (iz = z0; iz <= z1; iz++) {
        for (iy = y0; iy <= y1; iy++) {
            for (ix = x0; ix <= x1; ix++) {
                if (is_solid(get_b(ix, iy, iz)))
                    return 1;
            }
        }
    }
    return 0;
}

typedef enum {
