    for (i = 0; i < len; i++) {
        crc ^= p[i];
        for (k = 0; k < 8; k++)
            crc = (crc & 1) ? (crc >> 1) ^ MC_SAVE_CRC_SEED : (crc >> 1);
    }
    return ~crc;
}

