/* Import a 64x64x32 legacy blob into chunks (0..3, 0..3), then dirty so
 * region files persist it. Old saves keep their world, new code owns it. */

static void carve_blob(const unsigned char *blob) {
    int cx, cy, x, y, z, s;
    for (cy = 0; cy < 4; cy++) {
        for (cx = 0; cx < 4; cx++)
            chunk_ensure(cx, cy);
    }
    for (y = 0; y < 64; y++) {
        for (x = 0; x < 64; x++) {
            for (z = 0; z < MC_H; z++) {
                unsigned char b = blob[(z * 64 + y) * 64 + x];
                if (b < B_COUNT)
                    set_b_raw(x, y, z, b);
            }
        }
    }
    for (cy = 0; cy < 4; cy++) {
        for (cx = 0; cx < 4; cx++) {
            s = chunk_find(cx, cy);
            if (s >= 0) {
                chunk_build_meta(s);
                ch_dirty[s] = 1;
            }
        }
    }
    world_max_recompute();
}

