/* ---- Hybrid palette ---- */
/* The desktop-exact hybrid palette lives once in progs/nk_palette.h;
 * this wrapper keeps the platform signature while sharing the table. */

void nk_build_palette(unsigned char *pal768) {
    if (nk_palette_build(pal768, NK_PAL_BYTES) != NK_PAL_ERR_OK)
        return;
}

/* ---- Color mapping ---- */
static int pal_r[241], pal_g[241], pal_b[241];
static int pal_ready;

static void pal_prepare(void) {
    unsigned char pal768[768];
    nk_build_palette(pal768);
    for (int i = 0; i < 241; i++) {
        pal_r[i] = pal768[(i+15)*3+0];
        pal_g[i] = pal768[(i+15)*3+1];
        pal_b[i] = pal768[(i+15)*3+2];
    }
    pal_ready = 1;
}

static int col_to_idx(struct nk_color c) {
    if (!pal_ready) pal_prepare();
    /* Dual-buffer side effect: the dispatching command's true color rides
     * along for the RGB buffer while the return value serves the indexed
     * one. Every drawing command resolves through here exactly once, so
     * no call site needs to change; TEXT repoints fg/bg explicitly. */
    cur_r = c.r; cur_g = c.g; cur_b = c.b;
    int best = 0;
    int bestd = 1 << 30;
    for (int i = 0; i < 241; i++) {
        int dr = pal_r[i] - c.r;
        int dg = pal_g[i] - c.g;
        int db = pal_b[i] - c.b;
        int d = dr*dr + dg*dg + db*db;
        if (d < bestd) { bestd = d; best = i; }
    }
    return best + 15;
}

/* ---- Software rasterizer ----
 * Dual-buffer: every command draws its palette index into NK_BACKBUF (the
 * legacy consumers: wl mirror, old kernels, --selftest marker) and, when
 * nk_rgb_available(), its true nk_color into NK_RGB_BUF. The current
 * command's colors ride in file-scope globals set once per command at the
 * nk_rasterize dispatch, so the shape helpers keep their signatures and
 * col_to_idx still runs once per command, never per pixel. IMAGE commands
 * own indexed pixels already and resolve through px_idx + rgb256 instead. */
static volatile uint8_t *fb = NK_BACKBUF;
static volatile uint8_t *fbrgb = NK_RGB_BUF;
static int clip_x, clip_y, clip_w, clip_h;

static void set_clip(int x, int y, int w, int h) {
    if (x < 0) { w += x; x = 0; }
    if (y < 0) { h += y; y = 0; }
    if (x + w > NK_W) w = NK_W - x;
    if (y + h > NK_H) h = NK_H - y;
    clip_x = x; clip_y = y; clip_w = w; clip_h = h;
    if (clip_w < 0) clip_w = 0;
    if (clip_h < 0) clip_h = 0;
}

static void px(int x, int y, int c) {
    volatile uint8_t *d;
    if (x < clip_x || x >= clip_x + clip_w) return;
    if (y < clip_y || y >= clip_y + clip_h) return;
    if (x < 0 || x >= NK_W || y < 0 || y >= NK_H) return;
    fb[y * NK_W + x] = (uint8_t)c;
    if (nk_rgb_on == 1) {
        d = fbrgb + ((y * NK_W) + x) * 3;
        d[0] = (uint8_t)cur_r; d[1] = (uint8_t)cur_g; d[2] = (uint8_t)cur_b;
    }
}

/* Text-background twin: same pixel, the command's background color. */

static void px_bg(int x, int y, int c) {
    volatile uint8_t *d;
    if (x < clip_x || x >= clip_x + clip_w) return;
    if (y < clip_y || y >= clip_y + clip_h) return;
    if (x < 0 || x >= NK_W || y < 0 || y >= NK_H) return;
    fb[y * NK_W + x] = (uint8_t)c;
    if (nk_rgb_on == 1) {
        d = fbrgb + ((y * NK_W) + x) * 3;
        d[0] = (uint8_t)cur_br; d[1] = (uint8_t)cur_bg; d[2] = (uint8_t)cur_bb;
    }
}

/* Index-owned pixels (IMAGE commands): RGB resolves through the exact
 * rgb256 table, so both buffers agree without a nearest search. */

static void px_idx(int x, int y, int c) {
    volatile uint8_t *d;
    unsigned char r, g, b;
    if (x < clip_x || x >= clip_x + clip_w) return;
    if (y < clip_y || y >= clip_y + clip_h) return;
    if (x < 0 || x >= NK_W || y < 0 || y >= NK_H) return;
    if (c < 0) c = 0;
    if (c > 255) c = 255;
    fb[y * NK_W + x] = (uint8_t)c;
    if (nk_rgb_on == 1) {
        nk_idx_to_rgb(c, &r, &g, &b);
        d = fbrgb + ((y * NK_W) + x) * 3;
        d[0] = r; d[1] = g; d[2] = b;
    }
}

static void fill_rect(int x, int y, int w, int h, int c) {
    if (w <= 0 || h <= 0) return;
    for (int yy = y; yy < y + h; yy++)
        for (int xx = x; xx < x + w; xx++)
            px(xx, yy, c);
}

static void draw_line(int x0, int y0, int x1, int y1, int th, int c) {
    int dx = x1 > x0 ? x1 - x0 : x0 - x1;
    int dy = y1 > y0 ? y1 - y0 : y0 - y1;
    int sx = x0 < x1 ? 1 : -1;
    int sy = y0 < y1 ? 1 : -1;
    int err = dx - dy;
    int r = th / 2;
    for (;;) {
        for (int ox = -r; ox <= r; ox++)
            for (int oy = -r; oy <= r; oy++)
                px(x0 + ox, y0 + oy, c);
        if (x0 == x1 && y0 == y1) break;
        int e2 = 2 * err;
        if (e2 > -dy) { err -= dy; x0 += sx; }
        if (e2 < dx)  { err += dx; y0 += sy; }
    }
}

static void fill_circle(int cx, int cy, int r, int c) {
    for (int y = -r; y <= r; y++)
        for (int x = -r; x <= r; x++)
            if (x*x + y*y <= r*r) px(cx + x, cy + y, c);
}

static void stroke_circle(int cx, int cy, int r, int th, int c) {
    int x = r, y = 0, err = 0;
    while (x >= y) {
        draw_line(cx - x, cy - y, cx - x, cy - y, th, c);
        draw_line(cx + x, cy - y, cx - x, cy - y, th, c);
        draw_line(cx - x, cy + y, cx - x, cy - y, th, c);
        draw_line(cx + x, cy + y, cx - x, cy - y, th, c);
        draw_line(cx - y, cy - x, cx - x, cy - y, th, c);
        draw_line(cx + y, cy - x, cx - x, cy - y, th, c);
        draw_line(cx - y, cy + x, cx - x, cy - y, th, c);
        draw_line(cx + y, cy + x, cx - x, cy - y, th, c);
        y++;
        if (err <= 0) { err += 2*y + 1; }
        if (err > 0)  { x--; err -= 2*x + 1; }
    }
}

/* Fill a convex polygon (x[], y[]). */

static void fill_poly(int *xs, int *ys, int n, int c) {
    if (n < 3) return;
    int miny = ys[0], maxy = ys[0];
    for (int i = 1; i < n; i++) {
        if (ys[i] < miny) miny = ys[i];
        if (ys[i] > maxy) maxy = ys[i];
    }
    for (int y = miny; y <= maxy; y++) {
        int hits[16], nh = 0;
        for (int i = 0; i < n && nh < 16; i++) {
            int j = (i + 1) % n;
            int yi = ys[i], yj = ys[j];
            if ((yi <= y && yj > y) || (yj <= y && yi > y)) {
                hits[nh++] = xs[i] + (int)((long)(y - yi) * (xs[j] - xs[i]) /
                                           (long)(yj - yi));
            }
        }
        for (int k = 0; k < nh; k += 2)
            for (int x = hits[k]; x <= hits[k+1] && x < clip_x + clip_w; x++)
                px(x, y, c);
    }
}

static void stroke_poly(int *xs, int *ys, int n, int th, int c) {
    for (int i = 0; i < n; i++) {
        int j = (i + 1) % n;
        draw_line(xs[i], ys[i], xs[j], ys[j], th, c);
    }
}

static void draw_text(int x, int y, const char *s, int len, int fg, int bg) {
    for (int k = 0; k < len; k++) {
        unsigned char ch = (unsigned char)s[k];
        if (ch < 32 || ch > 127) ch = '?';
        const uint8_t *glyph = nk_font8x8[ch - 32];
        for (int j = 0; j < 8; j++) {
            uint8_t bits = glyph[j];
            for (int i = 0; i < 8; i++)
                if (bits & (0x80 >> i)) px(x + k*8 + i, y + j, fg);
                else if (bg >= 0) px_bg(x + k*8 + i, y + j, bg);
        }
    }
}

static void draw_arc(int cx, int cy, int r, float a0, float a1,
                     int filled, int th, int c) {
    int ptsx[40], ptsy[40], n = 0;
    int segs = 32;
    for (int i = 0; i <= segs; i++) {
        float t = a0 + (a1 - a0) * (float)i / (float)segs;
        ptsx[n] = cx + (int)(r * cosf(t));
        ptsy[n] = cy + (int)(r * sinf(t));
        n++;
    }
    if (filled) {
        int allx[42], ally[42];
        allx[0] = cx; ally[0] = cy;
        for (int i = 0; i < n; i++) { allx[i+1] = ptsx[i]; ally[i+1] = ptsy[i]; }
        fill_poly(allx, ally, n + 1, c);
    } else {
        for (int i = 0; i < n - 1; i++)
            draw_line(ptsx[i], ptsy[i], ptsx[i+1], ptsy[i+1], th, c);
    }
}

