    if (x < 0 || y < 0 || x >= w || y >= h) return -1;
    oc = buf[y * w + x];
    if (oc == nc) return 0;
    buf[y * w + x] = nc;
    sx[top] = x;
    sy[top] = y;
    top++;
    n = 1;
    while (top > 0) {
        int cx;
        int cy;
        top--;
        cx = sx[top];
        cy = sy[top];
        if (top + 4 > PAINT_N) return -1;
