            if (dx < 0 || dx >= NK_W || dy < 0 || dy >= NK_H) continue;
            fb[dy * NK_W + dx] = paint_px[y * PAINT_W + x];
            if (!rgb) continue;
            nk_idx_to_rgb(paint_px[y * PAINT_W + x], &r, &g, &b);
            d = NK_RGB_BUF + ((dy * NK_W) + dx) * 3;
            d[0] = r; d[1] = g; d[2] = b;
