    int origin[2] = {0, 0};

         * wait below caps the frame rate (bench mode skips it so the
         * benchmark still measures raw throughput). */
        if (bench_ms <= 0) {
            while ((long)nk_sys_time_ms() - frame_t0 < PIANO_FRAME_PERIOD)
