/* ── Headless selftest (BDD hook) ───────────────────────────────────── */

static int run_selftest(void) {
    int i;
    audio_on = 1;
    OPL3_Reset(&o3, RATE);
    for (i = 0; i < NKEYS; i++) key_to_chan[i] = -1;
    for (i = 0; i < MAX_VOICES; i++) {
        chan_used[i] = 0;
        chan_sustained[i] = 0;
    }
    kbd_all_off();
    sustain_pedal = 0;
    octave = 0;
    fx_configure(0, 0, 0, 100);

    /* Velocity: the top of a key is soft, the bottom is loud. */
    int x, y, w, h;
    key_rect(0, &x, &y, &w, &h);
    int v_top = hit_velocity(0, y);
    int v_bot = hit_velocity(0, y + h - 1);
    if (!(v_top >= 1 && v_top <= 10 && v_bot >= 90 && v_bot <= 100)) {
        printf("piano: velocity range fail (%d..%d)\n", v_top, v_bot);
        return 1;
    }

    /* Sustain holds a released key until the pedal lifts. */
    sustain_pedal = 1;
    note_on_key(0, 60, 80);
    if (!chan_used[0]) { printf("piano: note_on did not grab a voice\n"); return 1; }
    note_off_key(0);
    if (!chan_sustained[0]) { printf("piano: sustain did not hold the release\n"); return 1; }
    if (!chan_used[0]) { printf("piano: sustain freed the voice early\n"); return 1; }
    pedal_set(0);
    if (chan_used[0] || chan_sustained[0]) {
        printf("piano: pedal release did not free the voice\n"); return 1;
    }
    sustain_pedal = 0;

    /* Octave transposition clamps to the MIDI range. */
    if (clamp_midi(127 + 12 * 6) != 127 || clamp_midi(0 - 12 * 6) != 0) {
        printf("piano: octave clamp fail\n"); return 1;

static int run_pcm2_probe(void) {
    static unsigned char pat[2048];
    long rc, acc;
    unsigned i;
    for (i = 0; i < sizeof pat; i++) pat[i] = (unsigned char)(i & 0xFF);
    rc = sys_pcm_open(MINIOS_PCM2_NONBLOCK);
    if (rc != 0) {
        printf("piano: pcm2 open refused (%ld)\n", rc);
        return 1;
    }
    acc = sys_pcm_write(pat, (long)sizeof pat);
    if (acc < 1024 || acc > 2048) {
        printf("piano: pcm2 short write (%ld)\n", acc);
        sys_pcm_close();
        return 1;
    }
    sys_pcm_close();
    rc = sys_pcm_open(MINIOS_PCM2_NONBLOCK);
    if (rc != 0) {
        printf("piano: pcm2 reopen refused (%ld)\n", rc);
        return 1;
    }
    sys_pcm_close();
    printf("pcm2: probe ok (accepted=%ld)\n", acc);
    return 0;
}

int main(int argc, char **argv) {
    if (argc > 1 && strcmp(argv[1], "--selftest") == 0)
        return run_selftest();
    if (argc > 1 && strcmp(argv[1], "--pcm2-probe") == 0)
        return run_pcm2_probe();
    if (argc > 1 && strcmp(argv[1], "--bench") == 0) {
        ui_run(2000);
        return 0;
    }
    ui_run(0);
    return 0;
}

