static int pokemon_art_load_one(const char *path, unsigned char **rgb,
                                int *w, int *h) {
    unsigned char *raw = 0;
    long raw_n = 0;
    unsigned char *px = 0;
    int iw = 0;
    int ih = 0;
    int comp = 0;
    if (!path || !rgb || !w || !h)
        return -1;
