    /* Simple comma-separated parse */
    const char *p = frames;
    while (*p && g_dump_count < 100) {
        uint32_t val = 0;
        while (*p >= '0' && *p <= '9') {
            val = val * 10 + (unsigned)(*p - '0');
            p++;
