int SWimp_Init(void *hInstance, void *wndProc) {
    sys_vga_mode(1);
    sys_set_title("Quake 2");
    if (!s_windowed && s_autoframes <= 0)
        sys_gfx_zoom(MINIOS_GFX_ZOOM_FULLSCREEN);
    sys_kbd_raw(1);
    return 1;
}

void SWimp_EndFrame(void) {
    if (palette_dirty) {
        sys_palette(q2_palette);
        palette_dirty = 0;
    }

    sys_doom_frame();
    kbd_poll();

    s_frame_count++;
    if (s_sndtest[0] && !s_sndtest_done && s_frame_count >= 10) {
        char cmd[96];
        strcpy(cmd, "play ");
        strcat(cmd, s_sndtest);
        strcat(cmd, "\nsoundlist\n");
        Cbuf_AddText(cmd);
        s_sndtest_done = 1;
    }

    if (s_autoframes > 0) {
        s_frames++;
        if (s_frames >= s_autoframes) {
            printf("minios: played %d frames, quitting\n", s_frames);
            fflush(stdout);
            Sys_Quit();
        }
    }
}

