    (void)active;
}

int QG_Milliseconds(void) {
    return (int)sys_time_ms();
}

int main(int argc, char **argv) {
    int time, oldtime, newtime;

    if (argc > 1 && strcmp(argv[1], "--pcm2-probe") == 0)
        return q2snd_probe();

    q2g_parse_autoframes(argc, argv);
    q2g_parse_sndtest(argc, argv);
    q2g_parse_windowed(argc, argv);

    Quake2_Init(argc, argv);

    int m[4] = { 0, 0, 0, 0 };
    if (sys_mouse(m) == 0) {
        s_prev_mouse_x = m[0];
        s_prev_mouse_y = m[1];
    }

    oldtime = Quake2_Milliseconds();
    while (1) {
        do {
            newtime = Quake2_Milliseconds();
            time = newtime - oldtime;
        } while (time < 1);

        Quake2_Frame(time);

        oldtime = newtime;
    }

    return 0;
}

#define Q2SND_BUF_BYTES (Q2SND_SAMPLES * 2)

static unsigned char q2_conv[1024];

static unsigned char *q2_dma_buf;
static int            q2_dma_open;
static long long      q2_dma_written;   /* frames handed to pcm2 so far */
static long long      q2_dma_start_ms;
static long long      q2_dma_loud;      /* pushed bytes clearly above silence */
static long long      q2_dma_total;

static long sys_pcm2_open(long flags) {
    long ret;
    __asm__ volatile("syscall" : "=a"(ret)
                     : "a"(MINIOS_SYS_PCM2_OPEN), "D"(flags)
                     : "rcx", "r11", "memory");
    return ret;
}

static long sys_pcm2_write(const void *buf, long len) {
    long ret;
    __asm__ volatile("syscall" : "=a"(ret)
                     : "a"(MINIOS_SYS_PCM2_WRITE), "D"(buf), "S"(len)
                     : "rcx", "r11", "memory");
    return ret;
}

static void sys_pcm2_close(void) {
    __asm__ volatile("syscall"
                     : : "a"(MINIOS_SYS_PCM2_CLOSE)
                     : "rcx", "r11", "memory");
}

static long sys_time_ms(void) {
    long ret;
    __asm__ volatile("syscall" : "=a"(ret)
                     : "a"(MINIOS_SYS_TIME), "D"(0)
                     : "rcx", "r11", "memory");
    return ret;
}

/* Push the freshly painted range [q2_dma_written, end) in ring order with
 * NONBLOCK writes that take what the kernel ring has room for. The mixer
 * ring is 16-bit mono; each frame is downconverted to 8-bit unsigned for
 * pcm2 in bounded sub-chunks. A short count is not loss: the frames wait
 * in dma.buffer (the engine only wraps far behind the paint lead) and go
 * out on the next Submit. Returns the number of frames handed to the
 * device. */

static int q2_dma_push(int end) {
    int pushed = 0;
    while (q2_dma_written < end) {
        int idx = (int)(q2_dma_written & (Q2SND_SAMPLES - 1));
        int n = end - (int)q2_dma_written;
        int m, k;
        long r;
        short *src;
        if (n > Q2SND_SAMPLES - idx) n = Q2SND_SAMPLES - idx;
        if (n > (int)sizeof(q2_conv)) n = (int)sizeof(q2_conv);
        src = (short *)(q2_dma_buf + (unsigned)idx * 2u);
        for (k = 0; k < n; k++) {
            int v = (int)src[k] >> 8;
            if (v > 127) v = 127;
            else if (v < -128) v = -128;
            q2_conv[k] = (unsigned char)(v + 128);
        }
        r = sys_pcm2_write(q2_conv, n);
        if (r <= 0) break;
        /* Loudness probe on the accepted prefix only, so a retry never
         * double-counts: anything clearly off the 0x80 line is real mixed
         * audio, not padding. */
        for (k = 0; k < r; k++) {
            int d = (int)q2_conv[k] - (int)Q2SND_SILENCE;
            if (d < 0) d = -d;
            if (d > 4) q2_dma_loud++;
        }
        q2_dma_total += r;
        q2_dma_written += r;
        pushed += (int)r;
    }
    return pushed;
}

qboolean SNDDMA_Init(void) {
    memset(&dma, 0, sizeof(dma));

    if (sys_pcm2_open(MINIOS_PCM2_NONBLOCK) < 0) {
        Com_Printf("pcm2 unavailable, sound disabled\n");
        return false;
    }

    q2_dma_buf = (unsigned char *)malloc(Q2SND_BUF_BYTES);
    if (!q2_dma_buf) {
        sys_pcm2_close();
        Com_Printf("sound buffer allocation failed, sound disabled\n");
        return false;
    }
    memset(q2_dma_buf, 0, Q2SND_BUF_BYTES);

    dma.channels = 1;
    dma.samples = Q2SND_SAMPLES;
    dma.submission_chunk = 1;
    dma.samplepos = 0;
    dma.samplebits = 16;
    dma.speed = Q2SND_RATE;
    dma.buffer = q2_dma_buf;

    q2_dma_open = 1;
    q2_dma_written = 0;
    q2_dma_start_ms = sys_time_ms();

    Com_Printf("pcm2 dma: %d Hz, %d mono samples (16-bit mixer)\n",
               dma.speed, dma.samples);
    return true;
}

/* Frames the device has finished, from the audio clock. Clamped to what has
 * actually been submitted so the engine (and the Submit window) can never
 * run ahead of the hardware. */
static long long q2_dma_played(void) {
    long long played =
        ((long long)(sys_time_ms() - q2_dma_start_ms) * Q2SND_RATE) / 1000;
    if (played < 0) played = 0;

int SNDDMA_GetDMAPos(void) {
    long long played;
    if (!q2_dma_open) return 0;
    played = q2_dma_played();
    dma.samplepos = (int)(played & (Q2SND_SAMPLES - 1));
    return dma.samplepos;
}

void SNDDMA_Shutdown(void) {
    if (!q2_dma_open) return;
    Com_Printf("q2snd: pushed %lld bytes (%lld loud)\n",
               q2_dma_total, q2_dma_loud);
    if (q2_dma_loud > 0) Com_Printf("q2snd: audio present\n");
    sys_pcm2_close();
    free(q2_dma_buf);
    q2_dma_buf = NULL;
    dma.buffer = NULL;
    q2_dma_open = 0;
}

void SNDDMA_Submit(void) {
    long long played, horizon;
    if (!q2_dma_open) return;
    if (paintedtime < q2_dma_written) q2_dma_written = paintedtime;
    /* Feed at most one kernel ring ahead of the play position; anything
     * further painted stays in dma.buffer for a later Submit. Pushing the
     * whole painted lead here would stall the frame for ~200 ms. */
    played = q2_dma_played();
    horizon = played + Q2SND_AHEAD;
    if (horizon > paintedtime) horizon = paintedtime;
    q2_dma_push((int)horizon);
}

/* Headless plumbing probe (BDD hook): open pcm2, stream one pattern, close,
 * report. Needs no game data, so it runs on a bare boot with the SB16
 * attached and is the serial proof that the Quake 2 backend reaches the
 * low-latency path. */

int q2snd_probe(void) {
    unsigned char pat[512];
    long rc, n;
    int i;

    for (i = 0; i < (int)sizeof(pat); i++)
        pat[i] = (unsigned char)(Q2SND_SILENCE + ((i * 5) & 0x3f) - 32);

    rc = sys_pcm2_open(0);
    if (rc < 0) {
        printf("q2snd: pcm2 open refused (%ld)\n", rc);
        return 1;
    }
    n = sys_pcm2_write(pat, (long)sizeof(pat));
    if (n != (long)sizeof(pat)) {
        printf("q2snd: pcm2 short write (%ld)\n", n);
        sys_pcm2_close();
        return 1;
    }
    sys_pcm2_close();
    printf("q2snd: pcm2 ok (accepted=%ld)\n", n);
    return 0;
}

#define AES_EXIT_FAIL 1

static int aes_rk[AES_RK_LEN];
static int aes_sb[AES_SBOX_SIZE];
static int aes_rc[AES_RCON_SIZE];
static int aes_st[AES_BLOCK];
static int aes_iv[AES_BLOCK];

static char *aes_read_all(const char *name, int *len) {
    char *data;
    int got;
    void *f = fopen((char *)name, "r");
    if (!f) return 0;
    fseek(f, 0, AES_SEEK_END);
    *len = ftell(f);
    rewind(f);
    if (*len < 0) { fclose(f); return 0; }
    data = malloc(*len > 0 ? *len : 1);
    if (!data) { fclose(f); return 0; }
    got = fread(data, 1, *len, f);
    fclose(f);
    if (got != *len) { free(data); return 0; }
    return data;
}

static int aes_write_all(const char *name, char *data, int len) {
    int n;
    void *f = fopen((char *)name, "w");
    if (!f) return 0;
    n = fwrite(data, 1, len, f);
    if (n != len) { fclose(f); return 0; }
    if (fclose(f) != 0) return 0;
    return 1;
}

static int aes_has(const char *s, const char *needle) {
    int i, j, n;
    n = strlen(needle);
    if (n <= 0) return 0;
    for (i = 0; s[i] != 0; i++) {
        for (j = 0; j < n; j++) {
            if (s[i + j] == 0) return 0;
            if (s[i + j] != needle[j]) break;
        }
        if (j == n) return 1;
    }
    return 0;
}

static int hex_val(int c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

static int aes_parse_hex(const char *s, int want, int *out) {
    int i, hi, lo;
    if ((int)strlen(s) != want) return 0;
    for (i = 0; i < want; i += 2) {
        hi = hex_val(s[i]);
        lo = hex_val(s[i + 1]);
        if (hi < 0 || lo < 0) return 0;
        out[i / 2] = hi * 16 + lo;
    }
    return 1;
}

/* Multiply in GF(2^8) modulo the AES polynomial; both operands are 0..255. */

static int aes_gf_mul(int a, int b) {
    int p;
    p = 0;
    while (b > 0) {
        if ((b & 1) != 0) p = p ^ a;
        a = a << 1;
        if ((a & 256) != 0) a = a ^ AES_POLY;
        b = b >> 1;
    }
    return p & 255;
}

static int aes_xtime(int x) {
    x = x << 1;
    if ((x & 256) != 0) x = x ^ AES_POLY;
    return x & 255;
}

static int aes_rotl8(int x, int n) {
    return ((x << n) | (x >> (8 - n))) & 255;
}

/* Build the S-box from first principles: multiplicative inverse in GF(2^8)
 * composed with the FIPS-197 affine transform.  Zero maps straight to the
 * affine constant because 0 has no inverse. */

static void aes_init_tables(void) {
    int i, j, inv, s;
    aes_sb[0] = AES_AFFINE_C;
    for (i = 1; i < AES_SBOX_SIZE; i++) {
        inv = 0;
        for (j = 1; j < AES_SBOX_SIZE; j++) {
            if (aes_gf_mul(i, j) == 1) { inv = j; break; }
        }
        s = inv;
        for (j = 1; j <= 4; j++) s = s ^ aes_rotl8(inv, j);
        aes_sb[i] = s ^ AES_AFFINE_C;
    }
    aes_rc[0] = AES_RCON_PAD;
    for (i = 1; i < AES_RCON_SIZE; i++) aes_rc[i] = aes_xtime(aes_rc[i - 1]);
}

/* Expand the 32-byte key into AES_RK_LEN round-key bytes (FIPS-197 for
 * Nk=8, Nr=14: RotWord plus SubWord every Nk words, an extra SubWord pass
 * every Nk/2 words). */

static void aes_key_expand(const int *key) {
    int i, t0, t1, t2, t3, k, j;
    for (i = 0; i < AES_KEY_BYTES; i++) aes_rk[i] = key[i];
    for (i = AES_KEY_BYTES / 4; i < AES_RK_LEN / 4; i++) {
        k = (i - 1) * 4;
        t0 = aes_rk[k];
        t1 = aes_rk[k + 1];
        t2 = aes_rk[k + 2];
        t3 = aes_rk[k + 3];
        if ((i % 8) == 0) {
            j = t0;
            t0 = t1;
            t1 = t2;
            t2 = t3;
            t3 = j;
            t0 = aes_sb[t0] ^ aes_rc[i / 8];
            t1 = aes_sb[t1];
            t2 = aes_sb[t2];
            t3 = aes_sb[t3];
        }
        if ((i % 8) == 4) {
            t0 = aes_sb[t0];
            t1 = aes_sb[t1];
            t2 = aes_sb[t2];
            t3 = aes_sb[t3];
        }
        j = i * 4;
        k = (i - 8) * 4;
        aes_rk[j] = aes_rk[k] ^ t0;
        aes_rk[j + 1] = aes_rk[k + 1] ^ t1;
        aes_rk[j + 2] = aes_rk[k + 2] ^ t2;
        aes_rk[j + 3] = aes_rk[k + 3] ^ t3;
    }
}

static void aes_add_round_key(int round) {
    int i, base;
    base = round * AES_BLOCK;
    for (i = 0; i < AES_BLOCK; i++) aes_st[i] = (aes_st[i] ^ aes_rk[base + i]) & 255;
}

static void aes_sub_bytes(void) {
    int i;
    for (i = 0; i < AES_BLOCK; i++) aes_st[i] = aes_sb[aes_st[i]];
}

static void aes_shift_rows(void) {
    int t;
    t = aes_st[1]; aes_st[1] = aes_st[5]; aes_st[5] = aes_st[9]; aes_st[9] = aes_st[13]; aes_st[13] = t;
    t = aes_st[2]; aes_st[2] = aes_st[10]; aes_st[10] = t;
    t = aes_st[6]; aes_st[6] = aes_st[14]; aes_st[14] = t;
    t = aes_st[3]; aes_st[3] = aes_st[15]; aes_st[15] = aes_st[11]; aes_st[11] = aes_st[7]; aes_st[7] = t;
}

static void aes_mix_columns(void) {
    int c, t, m, tmp;
    for (c = 0; c < 4; c++) {
        t = aes_st[c * 4];
        tmp = aes_st[c * 4] ^ aes_st[c * 4 + 1] ^ aes_st[c * 4 + 2] ^ aes_st[c * 4 + 3];
        m = aes_st[c * 4] ^ aes_st[c * 4 + 1];
        m = aes_xtime(m);
        aes_st[c * 4] = (aes_st[c * 4] ^ tmp ^ m) & 255;
        m = aes_st[c * 4 + 1] ^ aes_st[c * 4 + 2];
        m = aes_xtime(m);
        aes_st[c * 4 + 1] = (aes_st[c * 4 + 1] ^ tmp ^ m) & 255;
        m = aes_st[c * 4 + 2] ^ aes_st[c * 4 + 3];
        m = aes_xtime(m);
        aes_st[c * 4 + 2] = (aes_st[c * 4 + 2] ^ tmp ^ m) & 255;
        m = aes_st[c * 4 + 3] ^ t;
        m = aes_xtime(m);
        aes_st[c * 4 + 3] = (aes_st[c * 4 + 3] ^ tmp ^ m) & 255;
    }
}

static void aes_cipher(void) {
    int r;
    aes_add_round_key(0);
    for (r = 1; r < AES_ROUNDS; r++) {
        aes_sub_bytes();
        aes_shift_rows();
        aes_mix_columns();
        aes_add_round_key(r);
    }
    aes_sub_bytes();
    aes_shift_rows();
    aes_add_round_key(AES_ROUNDS);
}

/* Big-endian increment of the whole counter block (SP 800-38A CTR). */

static void aes_iv_increment(void) {
    int b;
    for (b = AES_BLOCK - 1; b >= 0; b--) {
        aes_iv[b] = aes_iv[b] + 1;
        if (aes_iv[b] <= 255) break;
        aes_iv[b] = 0;
    }
}

/* XOR data in place with the keystream Cipher(nonce), Cipher(nonce+1)... */

static void aes_ctr_crypt(char *data, int len) {
    int i, j, bi;
    bi = AES_BLOCK;
    for (i = 0; i < len; i++) {
        if (bi == AES_BLOCK) {
            for (j = 0; j < AES_BLOCK; j++) aes_st[j] = aes_iv[j] & 255;
            aes_cipher();
            aes_iv_increment();
            bi = 0;
        }
        data[i] = (char)((data[i] & 255) ^ aes_st[bi]);
        bi++;
    }
}

static void aes_hdr_put(char *h, int size) {
    h[0] = AES_MAGIC0;
    h[1] = AES_MAGIC1;
    h[2] = AES_MAGIC2;
    h[3] = AES_MAGIC3;
    h[4] = (char)(size & 255);
    h[5] = (char)((size >> 8) & 255);
    h[6] = (char)((size >> 16) & 255);
    h[7] = (char)((size >> 24) & 255);
}

static int aes_hdr_get(char *h) {
    if (h[0] != AES_MAGIC0) return -1;
    if (h[1] != AES_MAGIC1) return -1;
    if (h[2] != AES_MAGIC2) return -1;
    if (h[3] != AES_MAGIC3) return -1;
    return (h[4] & 255) | ((h[5] & 255) << 8) | ((h[6] & 255) << 16) | ((h[7] & 255) << 24);
}

static const char *aes_tool_name(int decode) {
    if (decode) return "unaes";
    return "aes";
}

static int aes_run(int decode, const char *keyhex, const char *noncehex,
                   const char *src, const char *dst) {
    static int key[AES_KEY_BYTES];
    static int nonce[AES_NONCE_BYTES];
    char *data;
    int n;
    int size;
    if (!aes_parse_hex(keyhex, HEX_KEY_LEN, key)) {
        printf("%s: %s: key must be %d hex digits\n", aes_tool_name(decode), keyhex, HEX_KEY_LEN);
        return AES_EXIT_FAIL;
    }
    if (!aes_parse_hex(noncehex, HEX_NONCE_LEN, nonce)) {
        printf("%s: %s: nonce must be %d hex digits\n", aes_tool_name(decode), noncehex, HEX_NONCE_LEN);
        return AES_EXIT_FAIL;
    }
    aes_init_tables();
    aes_key_expand(key);
    for (n = 0; n < AES_NONCE_BYTES; n++) aes_iv[n] = nonce[n] & 255;
    data = aes_read_all(src, &n);
    if (!data) {
        printf("%s: cannot open %s\n", aes_tool_name(decode), src);
        return AES_EXIT_FAIL;
    }
    if (decode) {
        if (n < AES_HDR_SIZE) {
            free(data);
            printf("unaes: %s: truncated header\n", src);
            return AES_EXIT_FAIL;
        }
        size = aes_hdr_get(data);
        if (size < 0) {
            free(data);
            printf("unaes: %s: bad magic\n", src);
            return AES_EXIT_FAIL;
        }
        if (size != n - AES_HDR_SIZE) {
            free(data);
            printf("unaes: %s: size mismatch\n", src);
            return AES_EXIT_FAIL;
        }

int main(int argc, char **argv) {
    int decode;
    int a;
    decode = (argc >= 1 && aes_has(argv[0], "unaes"));
    a = 1;
    if (!decode && argc >= 2 && strcmp(argv[1], "-d") == 0) {
        decode = 1;
        a = 2;
    }
    if (argc - a != 4) {
        if (decode) printf("usage: unaes <key-hex64> <nonce-hex32> <src> <dst>\n");
        else printf("usage: aes [-d] <key-hex64> <nonce-hex32> <src> <dst>\n");
        return AES_EXIT_FAIL;
    }
    return aes_run(decode, argv[a], argv[a + 1], argv[a + 2], argv[a + 3]);
}

