static long freedom_wl_clip_rect(FreedomWlConfig *c, long *x, long *y, long *w, long *h) {
    if (!c || !x || !y || !w || !h) {
        return -1L;
    }
    if (*w <= 0L || *h <= 0L) {
        return -1L;
    }
    if (*x < 0L) {
        *w += *x;
        *x = 0L;
    }
    if (*y < 0L) {
        *h += *y;
        *y = 0L;
    }
    if (*x >= c->surface_w || *y >= c->surface_h) {
        return -1L;
    }
    if (*x + *w > c->surface_w) {
        *w = c->surface_w - *x;
    }
    if (*y + *h > c->surface_h) {
        *h = c->surface_h - *y;
    }
    if (*w <= 0L || *h <= 0L) {
        return -1L;
    }
    return 0L;
}

