        : "rcx", "r11", "memory");
    return r;
}

static long mprotect_sys(long addr, long len, long prot) {
    long r;
    register long a2 asm("rsi") = len;
    register long a3 asm("rdx") = prot;
    __asm__ volatile("syscall"
        : "=a"(r)
        : "0"(10), "D"(addr), "r"(a2), "r"(a3)
        : "rcx", "r11", "memory");
