static int mtop_atoi(char *s) {
    int v;
    int i;
    int neg;
    v = 0;
    i = 0;
    neg = 0;
    if (s[0] == '-') {
        neg = 1;
        i = 1;
    }
    while (s[i] >= '0' && s[i] <= '9') {
        v = v * 10 + (s[i] - '0');
        i++;
    }
    if (neg) v = -v;
    return v;
}

static void mtop_putu(long v) {
    char buf[24];
    int i;
    i = 24;
    i--;
    buf[i] = 0;
    if (v < 0) {
        emit("-");
        v = -v;
    }
    if (v == 0) {
        i--;
        buf[i] = '0';
    }
    while (v > 0 && i > 0) {
        i--;
        buf[i] = (char)('0' + v % 10);
        v = v / 10;
    }
    emit(&buf[i]);
}

