    }
    mb = kb / 1024;
    dec = ((kb % 1024) * 10) / 1024;
    mtop_putu(mb);
    emit(".");
    mtop_putu(dec);
    emit(" MB");
}

static void mtop_bar(long v, long max, int w) {
    int fill;
