    if (max < 1) max = 1;
    if (v < 0) v = 0;
    fill = (int)((v * w) / max);
    if (fill > w) fill = w;
    putchar('[');
    for (i = 0; i < w; i++) {
        if (i < fill) putchar('#');
        else putchar('-');
    }
    putchar(']');
}

