}

static long mtop_cpu(long *count, long *busy) {
    long total;
    long idle;
    long n;
    long up;
    long dt;
    long di;
    total = 0;
    idle = 0;
    n = 0;
    up = 0;
    if (mtop_minfo(4, &n, &up) != 0) return -1;
    if (n < 1) return -1;
    if (n > 64) return -1;
    if (mtop_minfo(3, &total, &idle) != 0) return -1;
    if (total <= 0) return -1;
    if (idle < 0) return -1;
    if (idle > total) return -1;
    *count = n;
    if (!have_prev) {
        prev_total = total;
        prev_idle = idle;
        have_prev = 1;
        return 1;
    }
    dt = total - prev_total;
    di = idle - prev_idle;
    prev_total = total;
    prev_idle = idle;
    if (dt <= 0) return 1;
    if (di < 0) di = 0;
    if (di > dt) di = dt;
    *busy = ((dt - di) * 100) / dt;
    return 0;
}

