    for (i = 0; i < BUF; i++) {
        outbuf[i] = (unsigned char)(128 + 60 * sin(2.0 * 3.14159265 * 440.0 * ph / RATE));
        ph += 1.0;
    }

    long start = call(SYS_TIME, 0, 0, 0);
    long last = start;
