static void spin_pixels(long off) {
    int y;
    int x;
    for (y = 0; y < SPIN_WLH; y++) {
        for (x = 0; x < SPIN_WLW; x++) {
            int pick = ((x + (int)off) / 16) & 1;
            spin_raw[y * SPIN_WLW + x] =
                (unsigned char)(pick ? SPIN_WLB : SPIN_WLA);
        }
    }
