static int tokenize_string(const char *text, int *tokens, int max_tokens) {
    int pos = 0;
    int tcount = 0;
    while (text[pos] && tcount < max_tokens) {
        unsigned char b = (unsigned char)text[pos];
        tokens[tcount++] = tokenize_byte(b);
        pos++;
    }
    return tcount;
}

