static int vedit_is_kw(const char *table, const char *word, int wlen) {
    int i = 0;
    if (wlen <= 0) return 0;
    while (table[i]) {
        int j = 0;
        while (table[i] == ' ') i++;
        if (!table[i]) break;
        while (table[i + j] && table[i + j] != ' ' &&
               j < wlen && table[i + j] == word[j])
            j++;
        if (j == wlen && (table[i + j] == ' ' || table[i + j] == 0))
            return 1;
        while (table[i] && table[i] != ' ') i++;
    }
    return 0;
}

