        int codes[] = {VEDIT_KEY_UP, VEDIT_KEY_DOWN, VEDIT_KEY_LEFT,
                       VEDIT_KEY_RIGHT, VEDIT_KEY_HOME, VEDIT_KEY_END,
                       VEDIT_KEY_PGUP, VEDIT_KEY_PGDN, VEDIT_KEY_DEL,
