static int vedit_sh_split(const char *line, char *buf, const char **argv) {
    int argc = 0;
    int k = 0;
    if (!line || !buf || !argv) return -1;
    while (*line) {
        while (*line == ' ' || *line == '\t') line++;
        if (!*line) break;
        if (argc >= VEDIT_SH_ARGS) return -1;
        argv[argc++] = buf + k;
        while (*line && *line != ' ' && *line != '\t') {
            if (k >= VEDIT_SH_LINE - 1) return -1;
            buf[k++] = *line++;
        }
        buf[k++] = 0;
    }
    argv[argc] = 0;
    return argc;
}

