    if (wl_pool_fit(w, h) != WL_ERR_OK)
        return WL_ERR_BOUND;
    if (wl_mbox_raw_name(path, sizeof path, box) <= 0)
        return WL_ERR_BOUND;
    f = fopen(path, "wb");
    if (!f)
        return WL_ERR_BOUND;
    n = (long)w * (long)h;
    if (fwrite(px, 1, (unsigned long)n, f) != (unsigned long)n) {
        fclose(f);
        return WL_ERR_BOUND;
    }
    if (fclose(f) != 0)
        return WL_ERR_BOUND;
    return WL_ERR_OK;
}

