        n++;
    if (path[n] != '-' || n == 0 || n >= WL_MBOX_BOX_MAX)
        return WL_ERR_STR;
    if (n + 1 >= boxcap)
        return WL_ERR_BOUND;
    for (i = 0; i < n; i++)
        box[i] = path[i];
    box[n] = '\0';
    if (wl_mbox_box_ok(box) != WL_ERR_OK)
