static inline int wl_scale_nearest(unsigned char *dst, int dw, int dh,
        const unsigned char *src, int sw, int sh) {
    int y;
    int x;
    long n;
    if (!dst || !src)
        return WL_ERR_BOUND;
    if (dw <= 0 || dh <= 0 || sw <= 0 || sh <= 0)
        return WL_ERR_BOUND;
    if (dw > WL_SURF_MAX_W || dh > WL_SURF_MAX_H)
        return WL_ERR_BOUND;
    if (sw > WL_SURF_MAX_W || sh > WL_SURF_MAX_H)
        return WL_ERR_BOUND;
