static int t_mclass(int c, const char *cls) {
    int neg = 0;
    int hit = 0;
    if (!cls || cls[0] != '[') return 0;
    cls++;
    if (*cls == '^') {
        neg = 1;
        cls++;
    }
    while (*cls && *cls != ']') {
        if (cls[1] == '-' && cls[2] && cls[2] != ']') {
            if (c >= (unsigned char)cls[0] && c <= (unsigned char)cls[2])
                hit = 1;
            cls += 3;
        } else {
            if (c == (unsigned char)*cls) hit = 1;
            cls++;
        }
    }
    return neg ? !hit : hit;
}

