def compute_cohesion(community_nodes, community_edges):
    """Compute cohesion as internal_edges / max_possible_edges."""
    n = len(community_nodes)
    if n < 2:
        return 1.0
    max_edges = n * (n - 1) // 2
    if max_edges == 0:
        return 1.0
    return len(community_edges) / max_edges

def extract_communities(cpg):
    """Extract communities and their internal edges from CPG."""
    communities = {}
    nodes = cpg.get("@graph", []) if isinstance(cpg, dict) else []

    for node in nodes:
        if isinstance(node, dict):
            comm = node.get("community", node.get("communityId", "default"))
            nid = node.get("@id", node.get("id", ""))
            if comm not in communities:
                communities[comm] = {"nodes": [], "edges": []}
            communities[comm]["nodes"].append(nid)

    return communities

def load_approval(policy_path):
    """Load explicit complexity approval from ARCH_POLICY.yaml."""
    if not os.path.exists(policy_path):
        return False, 0

    with open(policy_path, "r") as f:
        content = f.read()

    # Simple YAML-like parsing for kernel_symbol_limit
    match = re.search(r'kernel_symbol_limit:\s*(\d+)', content)
    if match:
        return True, int(match.group(1))
    return False, 0

def check_stubs(text, cfg):
    """Collect failure strings for stubs that do not fail closed."""
    failures = []
    for name in cfg.handlers:
        body = handler_body(text, name)
        if not body:
            failures.append(name + ": handler not found")
            continue
        if cfg.enosys_literal not in body:
            failures.append(name + ": missing ENOSYS answer")
        if cfg.success_pattern.search(body):
            failures.append(name + ": answers success")
    return failures

def regenerate_kb():
    """Attempt to regenerate KNOWLEDGE_BASE.md using readmenator."""
    if not os.path.exists(READMENATOR):
        return None

    try:
        result = subprocess.run(
            [sys.executable, READMENATOR, "--output", DEFAULT_KB],
            capture_output=True, text=True, timeout=120
        )
        if result.returncode == 0 and os.path.exists(DEFAULT_KB):
            with open(DEFAULT_KB, "r") as f:
                return f.read()
    except (subprocess.TimeoutExpired, FileNotFoundError):
        pass

    return None

def bash_unquote(expr):
    """Collapse the escapes bash applies inside the MUTATIONS string."""
    out = []
    i = 0
    while i < len(expr):
        ch = expr[i]
        if ch == "\\" and i + 1 < len(expr) and expr[i + 1] in '$`"\\\n':
            out.append(expr[i + 1])
            i += 2
            continue
        out.append(ch)
        i += 1
    return "".join(out)

