def build_graph(cpg):
    """Build adjacency list from CPG nodes and edges."""
    nodes = {}
    edges = defaultdict(list)

    graph = cpg.get("@graph", []) if isinstance(cpg, dict) else []
    for item in graph:
        if isinstance(item, dict):
            nid = item.get("@id", item.get("id", ""))
            comm = item.get("community", item.get("communityId", "default"))
            nodes[nid] = comm

    for item in graph:
        if isinstance(item, dict):
            src = item.get("@id", item.get("id", ""))
            dst = item.get("target", item.get("to", ""))
            if src in nodes and dst in nodes:
                edges[src].append(dst)
                edges[dst].append(src)

    return nodes, edges

def bfs_min_hops(nodes, edges, source, target_community, max_hops):
    """BFS from source to any node in target_community, returning hop count."""
    if source not in nodes:
        return float("inf")

    source_community = nodes[source]
    visited = {source}
    queue = deque([(source, 0)])

    while queue:
        current, hops = queue.popleft()
        if hops > max_hops:
            break

        for neighbor in edges.get(current, []):
            if neighbor in visited:
                continue
            visited.add(neighbor)

            neighbor_comm = nodes.get(neighbor, "default")
            if (neighbor_comm == target_community and
                    neighbor != source and
                    hops + 1 > 0):
                return hops + 1

            if hops + 1 < max_hops:
                queue.append((neighbor, hops + 1))

    return float("inf")

def find_surprising_connections(nodes, edges, min_hops):
    """Find connections of min_hops or more between distinct communities."""
    communities = defaultdict(list)
    for nid, comm in nodes.items():
        communities[comm].append(nid)

    surprising = []

    for comm_a, nodes_a in communities.items():
        for comm_b, nodes_b in communities.items():
            if comm_a >= comm_b:
                continue
            for node_a in nodes_a:
                for node_b in nodes_b:
                    hops = bfs_min_hops(nodes, edges, node_a, comm_b,
                                        min_hops + 1)
                    if hops >= min_hops:
                        surprising.append({
                            "from": node_a,
                            "from_community": comm_a,
                            "to": node_b,
                            "to_community": comm_b,
                            "hops": hops,
                        })
                        break
                if surprising and surprising[-1]["from_community"] == comm_a:
                    break

    return surprising

def split_functions(lines):
    """Yield (name, start, body_lines) triples using brace depth."""
    funcs = []
    i = 0
    cfg = Config()
    case_pattern = re.compile(r"^\s*(case\s+\d+\s*:|default\s*:)")
    while i < len(lines):
        match = cfg.func_pattern.match(lines[i])
        if not match:
            i += 1
            continue
        name = match.group(1)
        depth = 0
        body = []
        started = False
        while i < len(lines):
            line = lines[i]
            depth += line.count("{") - line.count("}")
            if "{" in line:
                started = True
            if started:
                body.append((i + 1, line))
            i += 1
            if started and depth <= 0:
                break
        if name == "ksyscall_dispatch":
            block = []
            block_name = name + ":head"
            for lineno, line in body:
                if case_pattern.match(line):
                    if block:
                        funcs.append((block_name, block))
                    block_name = "%s:%s" % (name, line.strip())
                    block = [(lineno, line)]
                else:
                    block.append((lineno, line))
            if block:
                funcs.append((block_name, block))
        else:
            funcs.append((name, body))

def checked_names(body):
    """Return identifiers named inside sanitizer checks in a body."""
    names = set()
    for _, line in body:
        for pattern in Config.check_patterns:
            for args in pattern.findall(line):
                names.update(re.findall(r"[A-Za-z_]\w*", args))
    return names

def delegated_only(body, alias):
    """Decide whether an alias flows only into sanitizing callees."""
    uses = []
    for _, line in body:
        if re.search(r"\b" + re.escape(alias) + r"\b", line):
            uses.append(line)
    bare = [u for u in uses if not Config.cast_pattern.search(u)]
    if not bare:
        return True
    for line in bare:
        if re.search(r"\b" + re.escape(alias) + r"\s*(\[|->|\*)", line):
            return False
        if re.search(r"\*\s*" + re.escape(alias) + r"\b", line):
            return False
        callee = re.search(r"(\w+)\s*\([^;]*\b" + re.escape(alias) + r"\b", line)
        if callee and callee.group(1) not in Config.delegated_callees:
            if "SANITIZE" not in line and "user_" not in line:
                return False
    return True

def split_top_args(argtext):
    """Split a call argument list on top-level commas only."""
    parts = []
    depth = 0
    cur = ""
    for ch in argtext:
        if ch in "([":
            depth += 1
        elif ch in ")]":
            depth -= 1
        if ch == "," and depth == 0:
            parts.append(cur)
            cur = ""
        else:
            cur += ch
    parts.append(cur)
    return parts

def audit_body(name, body):
    """Return violation strings for one function body."""
    violations = []
    checked = checked_names(body)
    pointers = {}
    scalars = {}
    for lineno, line in body:
        for alias, arg in Config.alias_pattern.findall(line):
            pointers.setdefault(alias, (arg, lineno))
        for alias, arg in Config.scalar_pattern.findall(line):
            if alias not in pointers:
                scalars.setdefault(alias, (arg, lineno))
    for alias, (arg, cast_line) in pointers.items():
        if alias in checked or arg in checked:
            continue
        if delegated_only(body, alias):
            continue
        violations.append(
            "%s:%d: %s (from %s) may dereference without a check"
            % (name, cast_line, alias, arg)
        )
    for alias, (arg, cast_line) in scalars.items():
        if alias in checked or arg in checked:
            continue
        for _, line in body:
            callee = re.search(r"(\w+)\s*\([^;]*\b" + re.escape(alias) + r"\b", line)
            if callee and callee.group(1) in Config.dereferencing_callees:
                violations.append(
                    "%s:%d: %s (from %s) reaches %s without a check"
                    % (name, cast_line, alias, arg, callee.group(1))
                )
                break
    reported = set(violations)
    for _, line in body:
        for callee, positions in Config.callee_ptr_params.items():
            call = re.search(r"\b" + re.escape(callee) + r"\s*\((.*)\)\s*;?\s*$", line)
            if not call:
                continue

def audit_file(path):
    """Audit every handler in one file, return violation strings."""
    with open(path, "r") as handle:
        lines = handle.read().splitlines()
    out = []
    for name, body in split_functions(lines):
        for violation in audit_body(name, body):
            out.append(path + ":" + violation)
    return out

