            return 0
        else:
            print("unknown arg: %s" % arg)
            print(__doc__)
            return 2
        i += 1
    if not boot:
        print(__doc__)
        return 2
    if not checks and not interactive:
        checks = list(HyperConfig.CHECKS)
    return run_boot(checks, extra_shell, interactive)


