    """Fraction of near-black pixels inside box (x0, y0, x1, y1)."""
    crop = img.crop(box).convert("L")
    hist = crop.histogram()
    total = sum(hist)
    if total == 0:
        return 0.0
    return sum(hist[:Config.dark_level]) / float(total)

